const pageHeadline = (kicker, title, body, action='') => `<header class="ihx-page-head"><div><span>${esc(kicker)}</span><h1>${esc(title)}</h1><p>${esc(body)}</p></div>${action}</header>`;
const safeProviderLogo = value => {
  try {
    const url = new URL(String(value || ''));
    return url.protocol === 'https:' && !url.username && !url.password ? url.href : '';
  } catch { return ''; }
};
const providerBrandAliases = Object.freeze({
  discordbot:'discord', discordapp:'discord', microsoftoutlook:'outlook',
  outlookcalendar:'outlook', outlookmail:'outlook', googlemail:'gmail',
  gsheets:'googlesheets', gcalendar:'googlecalendar', gdrive:'googledrive',
  googledocument:'googledocs', googledoc:'googledocs',
  teams:'microsoftteams', microsoftonedrive:'onedrive', microsoftsharepoint:'sharepoint',
  perplexity:'perplexityai', visualstudiocode:'vscode', codex:'openai',
  claudecode:'claude', x:'twitter', twitterapi:'twitter', linkedinads:'linkedin',
  facebookads:'facebook', instagramforbusiness:'instagram',
  mondaycom:'monday', wordpresscom:'wordpress', huggingfacehub:'huggingface',
});
const providerBrand = toolkit => {
  const key=String(toolkit || '').toLowerCase().replace(/[^a-z0-9]/g,'');
  const canonical=Object.hasOwn(providerBrandAliases,key) ? providerBrandAliases[key] : key;
  return Object.hasOwn(providerBrands,canonical) ? providerBrands[canonical] : null;
};
const providerDisplayName = item => {
  const brand=providerBrand(item?.toolkit);
  if(brand)return brand.name;
  const name=String(item?.name || '').trim();
  if(name && !/^auth_config[_-]/i.test(name))return name;
  return String(item?.toolkit || 'App').replace(/[_-]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
};
let providerMarkSequence=0;
const platformBrandMark = toolkit => {
  const brand=providerBrand(toolkit);
  if(!brand)return icon('plug');
  const prefix=`provider-${++providerMarkSequence}-`;
  const body=brand.body.replace(/id="/g,`id="${prefix}`).replace(/href="#/g,`href="#${prefix}`).replace(/url\(#/g,`url(#${prefix}`);
  return `<svg class="provider-brand-svg" viewBox="${brand.viewBox}" ${brand.fill ? `fill="${brand.fill}"` : ''} aria-hidden="true" focusable="false">${body}</svg>`;
};
const connectedAppMark = item => {
  const toolkit=String(item?.toolkit || '').toLowerCase();
  const brand=providerBrand(toolkit);
  const logo=safeProviderLogo(item?.logo);
  const mark=brand ? platformBrandMark(toolkit) : logo ? `<img data-provider-logo src="${esc(logo)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer"><span class="connected-app-logo-fallback" hidden>${icon('plug')}</span>` : icon('plug');
  return `<span class="connected-app-mark" data-toolkit="${esc(toolkit)}" aria-hidden="true">${mark}</span>`;
};
const bindProviderLogoFallbacks = (root=document) => {
  root.querySelectorAll('[data-provider-logo]').forEach(img => {
    if(img.dataset.logoBound==='1')return;
    img.dataset.logoBound='1';
    const fallback=img.nextElementSibling;
    const fail=()=>{img.hidden=true;if(fallback)fallback.hidden=false;};
    img.addEventListener('error',fail,{once:true});
    if(img.complete && !img.naturalWidth)fail();
  });
};


function toast(message, tone = '') {
  let region = $('#toast-region');
  if (!region) { region = document.createElement('div'); region.id = 'toast-region'; document.body.appendChild(region); }
  const item = document.createElement('div'); item.className = `toast ${tone}`; item.role = 'status'; item.textContent = message; region.appendChild(item);
  setTimeout(() => item.remove(), 3600);
}
async function copyText(text, button) {
  try { await navigator.clipboard.writeText(text); toast('Copied to clipboard', 'success'); if (button) { const old = button.innerHTML, label=button.getAttribute('aria-label'); button.innerHTML = `${icon('check')} Copied`; button.setAttribute('aria-label', 'Copied to clipboard'); setTimeout(() => { if (button.isConnected) { button.innerHTML = old; if(label==null)button.removeAttribute('aria-label');else button.setAttribute('aria-label',label); } }, 1400); } }
  catch { toast('Clipboard access was blocked', 'error'); }
}
async function refreshGatewayStatus(force = false) {
  const label = $('[data-gateway-label]');
  if (!label) return;
  if (force || !state.gateway || Date.now() - state.gatewayCheckedAt > 30000) {
    const started=performance.now();
    try { state.gateway = { reachable: true, ...await api('/api/status'), checkMs:Math.round(performance.now()-started) }; }
    catch { state.gateway = { reachable: false }; }
    state.gatewayCheckedAt = Date.now();
  }
  const current = $('[data-gateway-label]');
  const detail = $('[data-gateway-detail]');
  const indicator = $('[data-gateway-indicator]');
  if (!current || !detail || !indicator) return;
  current.textContent = state.gateway.reachable ? 'Gateway responding' : 'Gateway unavailable';
  detail.textContent = state.gateway.reachable
    ? `${state.gateway.checkMs} ms status check · ${state.gateway.control_database ? 'DB configured' : 'DB unconfigured'}`
    : 'Latest status check failed';
  indicator.classList.toggle('is-unavailable', !state.gateway.reachable);
}
// Normalize only documented display collections. Do not alter arbitrary run
// metadata, authentication responses, or mutation payloads.
function normalizeCollections(path, data) {
  const endpoint = path.split('?')[0];
  const fields = {
    '/api/public/plans': ['plans', 'credit_packs'],
    '/api/dashboard': ['series'],
    '/api/usage': ['events'],
    '/api/usage/intelligence': ['recent_runs', 'recent_failures', 'series'],
    '/api/api-keys': ['keys'],
    '/api/monitors': ['monitors'],
    '/api/wallet': ['ledger'],
    '/api/billing/payments': ['payments'],
    '/api/account/sessions': ['sessions'],
  }[endpoint] || (/^\/api\/monitors\/[^/]+\/history$/.test(endpoint) ? ['runs'] : null);
  if (!fields) return data;
  const object = (value, field) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
      throw new Error(`Expected an object for ${endpoint}: ${field}`);
    }
    return value;
  };
  const collection = (value, field, records = true) => {
    if (value == null) return [];
    if (!Array.isArray(value)) throw new Error(`Expected an array for ${endpoint}: ${field}`);
    if (records) value.forEach((item, index) => object(item, `${field}[${index}]`));
    return value;
  };
  const result = {...object(data, 'response')};
  fields.forEach(field => { result[field] = collection(data[field], field); });
  if (endpoint === '/api/usage/intelligence') {
    const breakdowns = data.breakdowns == null ? {} : object(data.breakdowns, 'breakdowns');
    result.breakdowns = {...breakdowns};
    ['status', 'tool', 'provider'].forEach(field => {
      result.breakdowns[field] = collection(breakdowns[field], `breakdowns.${field}`);
    });
  }
  if (endpoint === '/api/api-keys') {
    result.keys = result.keys.map(key => ({...key, scopes: collection(key.scopes, 'keys.scopes', false)}));
  }
  return result;
}
async function api(path, options = {}) {
  const init = { credentials:'include', cache:'no-store', ...options, headers:{'Content-Type':'application/json', ...(options.headers || {})} };
  if (init.body && typeof init.body !== 'string') init.body = JSON.stringify(init.body);
  const response = await fetch(path, init); let data = {};
  try { data = await response.json(); } catch {}
  if (!response.ok) { const detail = data?.detail; const error = new Error(typeof detail === 'string' ? detail : detail?.message || data?.error || `Request failed (${response.status})`); error.status = response.status; error.code = detail?.code; error.requestId = detail?.request_id; error.usage = detail?.usage; error.result = detail?.result; throw error; }
  return (init.method || 'GET').toUpperCase() === 'GET' ? normalizeCollections(path, data) : data;
}
