async function dashRewards(){
  const d=await api('/api/rewards?limit=100');
  const a=d.account||{},wallet=d.wallet||{},catalog=d.catalog||[],redemptions=d.redemptions||[],codeRedemptions=d.code_redemptions||[],ledger=d.ledger||[],rule=d.earning_rule||{};
  const points=Number(a.points||0);
  const walletAvailable=Math.max(0,Number(wallet.monthly_credits||0)+Number(wallet.purchased_credits||0)-Number(wallet.reserved_credits||0));
  const spendPerPoint=Number(rule.usd_spend_per_point||0);
  dashboardShell('rewards',
    pageHead(
      'REWARDS',
      'Rewards & redemption',
      'Earn reward points from metered OpenCrawl usage. Redeem them for prizes that are fulfilled directly into your account.',
      '<span class="badge success">'+fmt(points)+' points</span>'
    )+
    '<section class="reward-summary">'+
      '<article class="reward-balance-card"><span>AVAILABLE POINTS</span><b>'+fmt(points)+'</b><small>'+fmt(a.lifetime_earned||0)+' earned · '+fmt(a.lifetime_redeemed||0)+' redeemed</small></article>'+
      '<article><span>WALLET AVAILABLE</span><b>'+walletMoney(walletAvailable,d)+'</b><small>'+walletMoney(wallet.purchased_credits||0,d)+' rollover balance</small><a data-link href="/dashboard/wallet">Open wallet '+icon('arrow')+'</a></article>'+
      '<article><span>EARNING RATE</span><b>1 point</b><small>per '+(spendPerPoint?paymentMoney(Math.round(spendPerPoint*100),'USD'):'metered spend')+' of OpenCrawl usage</small></article>'+
    '</section>'+
    (d.earned_now?'<div class="reward-earned-banner">'+icon('gift')+' <b>+'+fmt(d.earned_now)+' points earned</b><span>Your latest metered usage has been converted into rewards.</span></div>':'')+
    '<section class="reward-code-panel">'+
      '<div class="reward-code-copy"><span class="overline">COMMUNITY DROP</span><h2>Have a reward code?</h2><p>Codes shared in the OpenCrawl community can unlock points or wallet credit. Each account can claim a campaign once.</p></div>'+
      '<form id="reward-code-form" autocomplete="off"><label><span>REWARD CODE</span><input name="code" type="text" minlength="4" maxlength="64" placeholder="OPENCRAWL-XXXX" autocapitalize="characters" spellcheck="false" required></label><button class="btn primary" type="submit">'+icon('gift')+' Redeem code</button></form>'+
      (codeRedemptions.length?'<div class="reward-code-history"><span>RECENT CLAIMS</span>'+codeRedemptions.slice(0,4).map(x=>'<div><b>'+esc(x.label)+'</b><small>'+esc(x.code_hint)+' · '+when(x.created_at)+'</small><em>'+(x.reward_type==='points'?'+'+fmt(x.reward_value)+' pts':'+'+walletMoney(x.reward_value,d))+'</em></div>').join('')+'</div>':'')+
    '</section>'+
    '<header class="subhead reward-subhead"><span><span class="overline">PRIZE CATALOG</span><h2>Redeem your points</h2></span><small>Redemptions are final once a prize is fulfilled.</small></header>'+
    '<section class="reward-grid">'+
      (catalog.length?catalog.map(r=>{
        const enough=points>=Number(r.points_cost||0);
        const value=r.fulfillment_type==='wallet_credit'?walletMoney(r.fulfillment_value||0,d):'Prize';
        return '<article class="reward-card '+(enough?'available':'locked')+'">'+
          '<header><span>'+icon('gift')+'</span><em>'+esc(value)+'</em></header>'+
          '<h3>'+esc(r.name)+'</h3><p>'+esc(r.description||'')+'</p>'+
          '<div><b>'+fmt(r.points_cost)+' points</b><small>'+(enough?'Ready to redeem':fmt(Number(r.points_cost||0)-points)+' more needed')+'</small></div>'+
          '<button class="btn '+(enough?'primary':'')+'" data-redeem="'+esc(r.slug)+'" data-reward-name="'+esc(r.name)+'" '+(enough?'':'disabled')+'>'+(enough?'Redeem prize':'Locked')+'</button>'+
        '</article>';
      }).join(''):'<div class="smart-empty"><span><b>No rewards available</b><p>The prize catalog is currently empty.</p></span></div>')+
    '</section>'+
    '<section class="reward-history-grid">'+
      '<article class="card"><header><span><span class="overline">REDEMPTIONS</span><h2>Prize history</h2></span></header>'+
        (redemptions.length?'<div class="table-wrap"><table><thead><tr><th>Time</th><th>Prize</th><th>Points</th><th>Status</th><th>Delivered</th></tr></thead><tbody>'+
          redemptions.map(x=>'<tr><td>'+when(x.created_at)+'</td><td>'+esc(x.reward_name)+'</td><td>'+fmt(x.points_spent)+'</td><td><span class="badge '+(x.status==='fulfilled'?'success':'warning')+'">'+esc(x.status)+'</span></td><td>'+(x.fulfillment_type==='wallet_credit'?walletMoney(x.fulfillment_value||0,d):esc(x.fulfillment_reference||'Pending'))+'</td></tr>').join('')+
          '</tbody></table></div>':'<div class="smart-empty compact"><span><b>No redemptions yet</b><p>Your claimed prizes will appear here.</p></span></div>')+
      '</article>'+
      '<article class="card"><header><span><span class="overline">POINTS LEDGER</span><h2>Reward activity</h2></span></header>'+
        (ledger.length?'<div class="reward-ledger">'+ledger.slice(0,12).map(x=>'<div><span><b>'+esc(x.kind==='earn'?'Points earned':'Prize redeemed')+'</b><small>'+when(x.created_at)+' · '+esc(x.source)+'</small></span><em class="'+(Number(x.amount)>=0?'positive':'')+'">'+(Number(x.amount)>0?'+':'')+fmt(x.amount)+'</em></div>').join('')+'</div>':'<div class="smart-empty compact"><span><b>No reward activity yet</b><p>Metered usage earns points automatically.</p></span></div>')+
      '</article>'+
    '</section>'
  );
  $('#reward-code-form')?.addEventListener('submit',async e=>{
    e.preventDefault();
    const form=e.currentTarget,button=e.submitter||form.querySelector('button'),input=form.elements.code;
    const code=String(input.value||'').trim().toUpperCase();
    if(!code)return;
    if(!busy(button,true,'Checking code…'))return;
    try{
      const result=await api('/api/rewards/codes/redeem',{method:'POST',body:{code}});
      const campaign=result.campaign||{};
      const delivered=campaign.reward_type==='points'
        ? '+'+fmt(campaign.reward_value||0)+' reward points'
        : '+'+walletMoney(campaign.reward_value||0,result)+' wallet credit';
      toast((campaign.label?campaign.label+': ':'')+delivered,'success');
      input.value='';
      state.me=null;
      await ensureMe();
      await dashRewards();
    }catch(error){
      busy(button,false);
      toast(error.message,'error');
    }
  });
  document.querySelectorAll('[data-redeem]').forEach(button=>button.onclick=async()=>{
    const slug=button.dataset.redeem,name=button.dataset.rewardName||'this prize';
    if(!confirm('Redeem '+name+'? Reward points are deducted immediately once fulfilled.'))return;
    if(!busy(button,true,'Redeeming…'))return;
    const storageKey='opencrawl:reward-redemption:'+slug;
    let idempotencyKey='';
    try{
      idempotencyKey=sessionStorage.getItem(storageKey)||'rwd-'+(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));
      sessionStorage.setItem(storageKey,idempotencyKey);
    }catch{
      idempotencyKey='rwd-'+(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));
    }
    try{
      const result=await api('/api/rewards/'+encodeURIComponent(slug)+'/redeem',{
        method:'POST',
        headers:{'Idempotency-Key':idempotencyKey},
        body:{}
      });
      try{sessionStorage.removeItem(storageKey)}catch{}
      if(result.redemption?.status==='fulfilled'){
        toast(result.replayed?'Prize already delivered — showing the existing redemption':'Prize redeemed and delivered to your wallet','success');
      }else{
        toast(result.replayed?'Existing redemption restored':'Redemption submitted','success');
      }
      state.me=null;
      await ensureMe();
      await dashRewards();
    }catch(error){
      busy(button,false);
      toast(error.message,'error');
    }
  });
}

async function dashBilling(){const [p,s,pay]=await Promise.all([getPlans(),api('/api/billing/status'),api('/api/billing/payments')]),a=state.me.account||{};dashboardShell('billing',`${pageHead('COMMERCIAL','Billing & plans','Every plan includes the full tool catalog. Choose by credits, throughput and account limits.',`<span class="badge ${s.configured?'success':'warning'}">Razorpay ${s.configured?'ready':'pending'}</span>`)}<div class="current-plan card"><span><span class="overline">CURRENT PLAN</span><h2>${esc(a.plan_name||'Free')}</h2><p>${walletMoney(a.monthly_credits,a)} monthly wallet · resets ${when(a.current_period_end)}</p></span><div><span>Keys <b>${fmt(a.api_key_limit)}</b></span><span>Monitors <b>${fmt(a.monitor_limit)}</b></span><span>RPM <b>${fmt(a.rpm_limit)}</b></span></div></div>${planCards(p.plans)}<article class="card"><header><span><span class="overline">PAYMENTS</span><h2>Purchase history</h2></span><em>${icon('shield')} Verified server-side</em></header>${pay.payments.length?`<div class="table-wrap"><table><thead><tr><th>Created</th><th>Purpose</th><th>Amount</th><th>Status</th><th>Reference</th></tr></thead><tbody>${pay.payments.map(x=>`<tr><td>${when(x.created_at)}</td><td>${esc(x.purpose)}</td><td>${money(Number(x.amount_paise)/100)}</td><td><span class="badge ${['paid','captured'].includes(x.status)?'success':'warning'}">${esc(x.status)}</span></td><td><code>${esc(x.order_id||'—')}</code></td></tr>`).join('')}</tbody></table></div>`:'<div class="smart-empty compact"><span><b>No purchases yet</b><p>Captured payments appear here.</p></span></div>'}</article>`);$$('.plan-card a[href*="plan="]').forEach(a=>a.onclick=e=>{e.preventDefault();startCheckout('subscription',new URL(a.href).searchParams.get('plan'),a);});}
async function startCheckout(purpose,slug,trigger,extra={}){
  if(trigger&&!busy(trigger,true,'Opening checkout…'))return;
  try{
    const r=await api('/api/billing/create-order',{method:'POST',body:{purpose,slug,...extra}});
    if(!window.Razorpay)await new Promise((ok,no)=>{const s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.onload=ok;s.onerror=()=>no(new Error('Checkout could not load. Please try again.'));document.head.appendChild(s);});
    new Razorpay({key:r.key_id,order_id:r.order.id,amount:r.order.amount,currency:r.order.currency||'INR',name:'OpenCrawl',description:purpose==='credits'?(extra.amount_usd?'Custom wallet top-up':'Wallet top-up'):'Plan',theme:{color:'#5de1e6'},handler:async response=>{toast('Verifying payment with the server…');try{await api('/api/billing/verify',{method:'POST',body:response});toast('Payment verified','success');state.me=null;go(`/dashboard/${purpose==='credits'?'wallet':'billing'}`);}catch(error){toast(error.message,'error');}}}).open();
  }catch(error){toast(error.message,'error');}
  finally{if(trigger?.isConnected)busy(trigger,false);}
}
async function dashSettings(){const [s,sessions]=await Promise.all([api('/api/security/status'),api('/api/account/sessions')]),u=state.me.user;dashboardShell('settings',`${pageHead('ACCOUNT','Settings & security','Identity, login protection, active sessions and recovery.')}<div class="settings-grid"><section class="card"><header><span><span class="overline">PROFILE</span><h2>Account details</h2></span><span class="badge success">Verified</span></header><form id="profile-form" class="form-stack"><label>Email<input value="${esc(u.email)}" disabled></label><label>Display name<input name="display_name" value="${esc(u.display_name||'')}" maxlength="80" required></label><div class="linked-row"><i>GH</i><span><b>GitHub</b><small>${u.github_connected?'Connected':'Not connected'}</small></span><em class="badge ${u.github_connected?'success':'neutral'}">${u.github_connected?'Linked':'Optional'}</em></div><button class="btn">Save profile</button></form></section><section class="card"><header><span><span class="overline">SECURITY</span><h2>Protection status</h2></span><span class="badge ${s.two_factor_enabled?'success':'warning'}">${s.two_factor_enabled?'2FA enabled':s.two_factor_available?'2FA available':'2FA needs server configuration'}</span></header><div class="security-status"><div>${icon('check')}<span><b>Email verified</b><small>Privileged actions unlocked</small></span><em>On</em></div><div>${icon('shield')}<span><b>Authenticator 2FA</b><small>${s.two_factor_enabled?'Required after primary sign-in':'Add a second factor'}</small></span><button class="btn ${s.two_factor_enabled?'danger':'primary'} small" id="toggle-2fa">${s.two_factor_enabled?'Disable':'Set up'}</button></div>${s.two_factor_enabled?`<div>${icon('activity')}<span><b>Recovery codes</b><small>Regenerate when needed</small></span><button class="btn small" id="regen">Regenerate</button></div>`:''}</div></section><section class="card full"><header><span><span class="overline">SESSIONS</span><h2>Active web sessions</h2></span><button class="btn danger small" id="revoke-all">Sign out everywhere</button></header><div class="session-list">${sessions.sessions.map(x=>`<div>${icon('activity')}<span><b>${x.current?'This session':'Web session'}</b><small>Created ${when(x.created_at)} · expires ${when(x.expires_at)}</small></span><em class="badge ${x.current?'success':'neutral'}">${x.current?'Current':'Active'}</em><button class="btn small" data-session="${x.id}">Revoke</button></div>`).join('')}</div></section><section class="card full"><header><span><span class="overline">PASSWORD</span><h2>Change password</h2></span></header><form id="password-form" class="inline-form"><label>Current password<input type="password" name="current_password" required></label><label>New password<input type="password" name="new_password" minlength="8" required></label><button class="btn">Change and sign out</button></form></section></div>`);$('#profile-form').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/account/profile',{method:'PATCH',body:Object.fromEntries(new FormData(e.currentTarget))});state.me.user=r.user;toast('Profile updated','success');}catch(error){toast(error.message,'error');}};$('#toggle-2fa').onclick=()=>s.two_factor_enabled?showDisable2fa():showSetup2fa($('#toggle-2fa'));$('#regen')?.addEventListener('click',showRegenerate);$$('[data-session]').forEach(b=>b.onclick=async()=>{const r=await api(`/api/account/sessions/${b.dataset.session}/revoke`,{method:'POST'});if(r.signed_out){state.me=null;go('/login');}else dashSettings();});$('#revoke-all').onclick=async()=>{if(!confirm('Sign out every web session?'))return;await api('/api/account/sessions/revoke-all',{method:'POST'});state.me=null;go('/login');};$('#password-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/account/password',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});state.me=null;toast('Password changed; sessions revoked','success');go('/login');}catch(error){toast(error.message,'error');}};}
async function showSetup2fa(trigger){
  if(trigger&&!busy(trigger,true,'Preparing…'))return;
  try{
    const setup=await api('/api/auth/2fa/setup',{method:'POST'});
    const wrap=modal(`<div class="modal-head"><span><span class="overline">STEP 1 OF 2</span><h2>Set up authenticator</h2></span><button data-close aria-label="Close">×</button></div><div class="setup-panel"><div class="qr-panel"><img src="${esc(setup.qr_data_uri)}" width="176" height="176" alt="Authenticator setup QR code"><small>Scan with your authenticator</small></div><span><p>Add OpenCrawl in your authenticator app.</p>${codeBlock(setup.secret,'Manual key')}${codeBlock(setup.otpauth_uri,'Authenticator URI')}</span></div><form id="confirm-2fa" class="form-stack"><label>Current 6-digit code<input class="code-input" name="code" required maxlength="6" pattern="[0-9]{6}" inputmode="numeric" autocomplete="one-time-code"></label><button class="btn primary large">Verify and enable</button></form>`,true);
    $('#confirm-2fa',wrap).onsubmit=async e=>{
      e.preventDefault();const button=e.submitter||e.currentTarget.querySelector('button');busy(button,true,'Verifying…');
      try{const r=await api('/api/auth/2fa/confirm',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});showCodes(wrap,r.recovery_codes);}
      catch(error){busy(button,false);toast(error.message,'error');}
    };
  }catch(error){toast(error.message,'error');}
  finally{if(trigger?.isConnected)busy(trigger,false);}
}
function showCodes(wrap,codes){$('.modal',wrap).innerHTML=`<div class="modal-head"><span><span class="overline">FINAL STEP</span><h2>Save recovery codes</h2></span></div><div class="notice warning">Each code works once and will not appear again.</div><div class="recovery-grid">${codes.map(x=>`<code>${esc(x)}</code>`).join('')}</div><button class="btn" data-copy="${esc(codes.join('\n'))}">${icon('copy')} Copy all</button><label class="ack"><input type="checkbox" id="codes-saved"> I stored these separately.</label><button class="btn primary large" id="finish-2fa" disabled>Finish</button>`;bindCommon();$('.modal',wrap).focus();$('#codes-saved',wrap).onchange=e=>$('#finish-2fa',wrap).disabled=!e.target.checked;$('#finish-2fa',wrap).onclick=()=>{wrap.remove();dashSettings();};}
function showDisable2fa(){const wrap=modal(`<div class="modal-head"><span><span class="overline">SECURITY CHANGE</span><h2>Disable 2FA</h2></span><button data-close aria-label="Close dialog">×</button></div><div class="notice warning">Existing recovery codes will be invalidated.</div><form id="disable-2fa" class="form-stack"><label>Authenticator or recovery code<input name="code" required autocomplete="one-time-code"></label><button class="btn danger large">Disable 2FA</button></form>`);$('#disable-2fa',wrap).onsubmit=async e=>{e.preventDefault();const button=e.submitter||e.currentTarget.querySelector('button');busy(button,true,'Disabling…');try{await api('/api/auth/2fa/disable',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});wrap.remove();dashSettings();}catch(error){busy(button,false);toast(error.message,'error');}};}
function showRegenerate(){const wrap=modal(`<div class="modal-head"><span><span class="overline">RECOVERY</span><h2>Regenerate codes</h2></span><button data-close aria-label="Close dialog">×</button></div><form id="regen-form" class="form-stack"><label>Authenticator code<input name="code" required maxlength="6" pattern="[0-9]{6}" inputmode="numeric" autocomplete="one-time-code"></label><button class="btn primary">Generate new codes</button></form>`);$('#regen-form',wrap).onsubmit=async e=>{e.preventDefault();const button=e.submitter||e.currentTarget.querySelector('button');busy(button,true,'Generating…');try{const r=await api('/api/auth/2fa/recovery/regenerate',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});showCodes(wrap,r.recovery_codes);}catch(error){busy(button,false);toast(error.message,'error');}};}


const LEGAL_ALIASES={'/terms':'terms','/privacy':'privacy','/acceptable-use':'acceptable-use','/cookies':'cookies','/billing-policy':'billing','/security':'security'};
function legalDocs(){return window.IH_LEGAL_DOCS||{}}
function legalMeta(){return window.IH_LEGAL_META||{}}
function legalHref(slug){return `/legal/${slug}`}
function legalBlock(block){
  if(!block)return '';
  if(block.type==='p')return `<p>${esc(block.text)}</p>`;
  if(block.type==='ul')return `<ul>${(block.items||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
  if(block.type==='note')return `<aside class="ih-legal-callout"><b>${esc(block.title||'Note')}</b><p>${esc(block.text)}</p></aside>`;
  if(block.type==='table')return `<div class="ih-legal-table-wrap"><table><thead><tr>${(block.headers||[]).map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${(block.rows||[]).map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  return '';
}
function legalSideNav(active=''){
  return `<nav class="ih-legal-side" aria-label="Legal documents"><a class="${!active?'active':''}" data-link href="/legal"><b>Legal center</b></a>${Object.entries(legalDocs()).map(([slug,doc])=>`<a class="${slug===active?'active':''}" data-link href="${legalHref(slug)}"><b>${esc(doc.shortTitle||doc.title)}</b></a>`).join('')}</nav>`;
}
function renderLegalHub(){
  const items=legalDocs(),m=legalMeta();document.title='Legal Center — OpenCrawl';
  publicShell(`<main class="ih-legal-page"><section class="ih-legal-hero"><div class="container"><span class="ih-legal-kicker">TRUST / POLICY / CONTROL</span><h1>Rules that match the product.</h1><p>OpenCrawl can search, browse, extract, monitor, route, and execute. These documents define the boundaries around that power, the data it processes, and how paid usage works.</p><div class="ih-legal-meta"><span>Policy version <b>${esc(m.version||'current')}</b></span><span>Effective <b>${esc(m.effective||'')}</b></span><span>Governing law <b>${esc(m.governingLaw||'')}</b></span></div></div></section><section class="container ih-legal-hub"><div class="ih-legal-principles"><article><span>01</span><b>Authorized access only</b><p>Automation does not create permission you did not already have.</p></article><article><span>02</span><b>Scoped execution</b><p>Credentials, providers, costs, and external actions stay bounded and auditable.</p></article><article><span>03</span><b>Data minimization</b><p>Send connected services only what a requested operation reasonably needs.</p></article><article><span>04</span><b>Verified payment state</b><p>Paid capacity is fulfilled only after server-side confirmation of captured payment state.</p></article></div><div class="ih-legal-card-grid">${Object.entries(items).map(([slug,doc])=>`<a class="ih-legal-card" data-link href="${legalHref(slug)}"><span>${esc(doc.shortTitle||doc.title)}</span><h2>${esc(doc.title)}</h2><p>${esc(doc.summary)}</p><em>Read policy ${icon('arrow')}</em></a>`).join('')}</div><aside class="ih-legal-review"><div>${icon('shield')}<span><b>Implementation-aligned policies</b><p>These pages are versioned against current product behavior. Review them whenever payment behavior, data flows, providers, or the legal operator changes.</p></span></div><a data-link href="/legal/security">Security policy ${icon('arrow')}</a></aside></section></main>`);
}
function renderLegalDocument(slug){
  const items=legalDocs(),doc=items[slug],m=legalMeta();if(!doc)return renderLegalHub();document.title=`${doc.title} — OpenCrawl`;
  const toc=(doc.sections||[]).map(s=>`<a href="#${esc(s.id)}">${esc(s.title)}</a>`).join('');
  const related=(doc.related||[]).map(k=>items[k]?`<a data-link href="${legalHref(k)}">${esc(items[k].shortTitle||items[k].title)} ${icon('arrow')}</a>`:'').join('');
  publicShell(`<main class="ih-legal-page ih-legal-doc-page"><section class="container ih-legal-doc-head"><a class="ih-legal-back" data-link href="/legal">${icon('arrow')} Legal center</a><span class="ih-legal-kicker">OPENCRAWL / POLICY</span><h1>${esc(doc.title)}</h1><p>${esc(doc.summary)}</p><div class="ih-legal-meta"><span>Version <b>${esc(m.version||'current')}</b></span><span>Effective <b>${esc(m.effective||'')}</b></span><span>Updated <b>${esc(m.updated||'')}</b></span></div></section><section class="container ih-legal-layout">${legalSideNav(slug)}<article class="ih-legal-article"><nav class="ih-legal-toc"><b>On this page</b>${toc}</nav>${(doc.sections||[]).map(s=>`<section id="${esc(s.id)}"><h2>${esc(s.title)}</h2>${(s.blocks||[]).map(legalBlock).join('')}</section>`).join('')}<footer class="ih-legal-related"><div><span>RELATED POLICIES</span>${related}</div><p>Policy version ${esc(m.version||'current')} · Last updated ${esc(m.updated||'')}</p></footer></article></section></main>`);
}
function renderLegal(){const path=location.pathname.replace(/\/+$/,'')||'/';const alias=LEGAL_ALIASES[path];if(alias)return renderLegalDocument(alias);if(path==='/legal')return renderLegalHub();const slug=path.startsWith('/legal/')?decodeURIComponent(path.slice(7)):'';return slug?renderLegalDocument(slug):renderLegalHub()}

async function dashGames(){
  const [data,keyData]=await Promise.all([api('/api/games'),api('/api/api-keys')]);
  const games=data.games||[],keys=(keyData.keys||[]).filter(k=>!k.revoked_at&&(!k.expires_at||new Date(k.expires_at)>new Date()));
  dashboardShell('games',`${pageHead('GAME INTELLIGENCE','Games & public data','Explore registered capabilities. OpenCrawl checks each operation when you open it.')}<section class="game-catalog"><label class="game-filter">Find a game<input id="game-search" type="search" placeholder="Search games" autocomplete="off"></label><p id="game-count" class="muted" role="status"></p><div id="game-list" class="game-list"></div><nav id="game-pagination" class="game-actions" aria-label="Game catalog pages"></nav><div id="game-detail" class="game-detail" aria-live="polite"></div></section>`);
  const list=$('#game-list'),detail=$('#game-detail'),filter=$('#game-search');
  const draw=()=>{
    const q=filter.value.trim().toLowerCase();
    const matches=games.filter(g=>g.name.toLowerCase().includes(q)||g.game_id.includes(q));
    const pages=Math.max(1,Math.ceil(matches.length/24));
    gamePage=Math.min(gamePage,pages-1);
    $('#game-count').textContent=`${fmt(matches.length)} games · page ${gamePage+1} of ${pages}. Availability is checked when you run an operation.`;
    const pager=$('#game-pagination');
    pager.innerHTML=pages>1?`<button type="button" class="btn" data-game-prev ${gamePage===0?'disabled':''}>Previous</button><button type="button" class="btn" data-game-next ${gamePage===pages-1?'disabled':''}>Next</button>`:'';
    pager.querySelector('[data-game-prev]')?.addEventListener('click',()=>{gamePage--;draw();filter.focus();});
    pager.querySelector('[data-game-next]')?.addEventListener('click',()=>{gamePage++;draw();filter.focus();});
    list.innerHTML=matches.length?matches.slice(gamePage*24,(gamePage+1)*24).map(g=>`<button class="game-tile" type="button" data-game="${esc(g.game_id)}" aria-pressed="${g.game_id===selectedId}" ${toolRunning?'disabled':''}><strong>${esc(g.name)}</strong><span>${fmt(g.capability_count)} capabilities · ${fmt(g.provider_ready_count)} ready</span>${icon('arrow')}</button>`).join(''):'<p class="game-empty">No registered game matches that search.</p>';
    $$('[data-game]',list).forEach(button=>button.onclick=()=>select(button.dataset.game));
  };
  let selectedRun=0,selectedId='',panelRun=0,toolRunning=false,gamePage=0;
  async function select(id){
    if(toolRunning)return;
    const run=++selectedRun;
    selectedId=id;panelRun++;draw();
    detail.innerHTML='<p class="game-empty">Loading capabilities…</p>';
    try{
      const {game}=await api('/api/games/'+encodeURIComponent(id));
      if(run!==selectedRun)return;
      detail.innerHTML=`<header><div><span class="overline">${esc(game.game_id)}</span><h2>${esc(game.name)}</h2><p>${fmt(game.capability_count)} registered capabilities · ${fmt(game.provider_ready_count)} ready to run. Open a capability to inspect its current operations.</p></div><div class="game-actions"><a class="btn primary" data-link href="/dashboard/playground?query=${encodeURIComponent(game.name+' latest patch and competitive meta')}">Research this game ${icon('arrow')}</a><a class="btn" data-link href="/dashboard/repositories?query=${encodeURIComponent(game.name+' public api tools')}">Find open-source tools</a></div></header><div class="game-capabilities">${(game.capabilities||[]).map(cap=>`<article><span class="game-cap-status ${cap.provider_ready?'ready':''}">${cap.provider_ready?(cap.providers.includes('gamecore')?(cap.id.startsWith('league.reference')?'Live reference':'Bundled reference'):'Ready to run'):cap.availability==='key_required'?'Access required':cap.availability==='discovery_required'?'Explore operations':'Currently unavailable'}</span><h3>${esc(cap.name)}</h3><p>${cap.providers.some(p=>['gamecore','gamepublic'].includes(p))?esc(cap.description):'Read public game data through a validated OpenCrawl operation.'}</p><small>${cap.provider_ready?'Execution available':cap.availability==='discovery_required'?'Operations checked on open':'No operation ready'}</small>${cap.providers.includes('gamecore')&&cap.provider_ready?`<button type="button" class="game-run-button" data-game-tool="${esc(cap.id)}">Run tool ${icon('arrow')}</button>`:cap.availability==='ready'||cap.availability==='discovery_required'?`<button type="button" class="game-run-button" data-game-discover="${esc(cap.id)}">${cap.provider_ready?'Run tool':'Find operations'} ${icon('arrow')}</button>`:''}</article>`).join('')}</div><div id="game-tool-panel" aria-live="polite"></div>`;
      const cards=$$('.game-capabilities > article',detail),grid=$('.game-capabilities',detail);
      const ready=cards.filter(card=>card.querySelector('.game-cap-status.ready'));
      const other=cards.filter(card=>!card.querySelector('.game-cap-status.ready'));
      ready.forEach(card=>grid.appendChild(card));
      if(other.length){
        const disclosure=document.createElement('details');
        disclosure.className='game-more-capabilities';
        disclosure.innerHTML=`<summary>${fmt(other.length)} more capabilities · inspect availability ${icon('arrow')}</summary><div class="game-capabilities"></div>`;
        other.forEach(card=>disclosure.querySelector('.game-capabilities').appendChild(card));
        grid.after(disclosure);
      }
      $$('[data-game-tool]',detail).forEach(button=>button.onclick=()=>showTool(game,button.dataset.gameTool));
      $$('[data-game-discover]',detail).forEach(button=>button.onclick=()=>showDiscoveredTool(game,button.dataset.gameDiscover));
    }catch(error){if(run===selectedRun)detail.innerHTML=`<p class="game-empty">${esc(error.message)}</p>`;}
  }
  async function showDiscoveredTool(game,capability){
    if(toolRunning)return;
    const currentPanel=++panelRun;
    const panel=$('#game-tool-panel',detail),cap=(game.capabilities||[]).find(c=>c.id===capability);
    panel.innerHTML=`<section class="game-tool-runner"><header><div><span class="game-agent-mark" aria-hidden="true">👾</span><span class="overline">OPENCRAWL / OPERATIONS</span><h3>${esc(cap?.name||capability)}</h3><p>Checking current read-only operations and required inputs…</p></div><button type="button" class="game-tool-close" aria-label="Close tool">×</button></header><div id="game-tool-options"></div></section>`;
    panel.querySelector('.game-tool-close').onclick=()=>{panelRun++;panel.replaceChildren();};
    panel.scrollIntoView({behavior:'smooth',block:'nearest'});
    try{
      const response=await api('/api/games/'+encodeURIComponent(game.game_id)+'/tools/'+encodeURIComponent(capability));
      if(currentPanel!==panelRun||!panel.isConnected)return;
      const tools=response.tools||[],box=$('#game-tool-options',panel);
      if(!tools.length){box.innerHTML='<p class="game-empty">No read-only operation is available right now. The connection or its access may need attention.</p>';return;}
      box.innerHTML=`<label>Choose an operation<select id="game-operation">${tools.map((tool,index)=>`<option value="${index}">${esc(tool.name)}</option>`).join('')}</select></label><div id="game-operation-form"></div>`;
      const selector=$('#game-operation',box);
      function renderOperation(){
        const tool=tools[Number(selector.value)],properties=tool.input_schema?.properties||{},required=tool.input_schema?.required||[];
        const fields=Object.entries(properties).filter(([key,schema])=>schema['x-in']!=='header'&&!['authorization','cookie','proxy-authorization','x-api-key'].includes(key.toLowerCase()));
        const fieldInput=(name,schema,index)=>{
          const requiredAttr=required.includes(name)?'required':'';
          const attr=`data-game-arg="${index}" ${requiredAttr}`;
          if(Array.isArray(schema.enum))return `<select ${attr}><option value="">Choose a value</option>${schema.enum.map((value,i)=>`<option value="${i}">${esc(String(value))}</option>`).join('')}</select>`;
          if(schema.type==='boolean')return `<select ${attr}><option value="">Choose a value</option><option value="true">True</option><option value="false">False</option></select>`;
          if(['object','array'].includes(schema.type))return `<textarea ${attr} rows="4" maxlength="4000" spellcheck="false" placeholder="${schema.type==='array'?'[]':'{}'}"></textarea>`;
          const number=['integer','number'].includes(schema.type);
          return `<input ${attr} ${number?'type="number"':'type="text"'} ${number?`step="${schema.type==='integer'?'1':'any'}"`:''} ${number&&Number.isFinite(schema.minimum)?`min="${esc(schema.minimum)}"`:''} ${number&&Number.isFinite(schema.maximum)?`max="${esc(schema.maximum)}"`:''} maxlength="512" placeholder="${esc(schema.description||name)}">`;
        };
        $('#game-operation-form',box).innerHTML=`<p>Read public game data. OpenCrawl validates these inputs before execution.</p><details class="game-operation-trace"><summary>Operation details</summary><p>${esc(tool.description||'Read-only public operation.')}</p><code>${esc(tool.metadata?.method||'GET')} ${esc(tool.metadata?.path||'')}</code></details>${keys.length?`<form id="game-discovered-form">${fields.map(([name,schema],index)=>`<label>${esc(name)}${required.includes(name)?' *':''}${fieldInput(name,schema,index)}</label>`).join('')}<label>OpenCrawl API key<select name="api_key_id">${keys.map(key=>`<option value="${esc(key.id)}">${esc(key.name)} · ${esc(key.prefix)}…</option>`).join('')}</select></label><button class="btn primary" type="submit">Run read-only operation ${icon('arrow')}</button></form>`:`<p>Create an OpenCrawl API key to run this operation.</p><a data-link class="btn primary" href="/dashboard/api-keys">Create API key</a>`}<div id="game-discovered-output" aria-live="polite"></div>`;
        const form=$('#game-discovered-form',box);if(!form)return;
        form.onsubmit=async event=>{
          event.preventDefault();if(toolRunning)return;
          const output=$('#game-discovered-output',box),submit=form.querySelector('button[type="submit"]'),arguments_={};
          try{
            fields.forEach(([name,schema],index)=>{
              const value=form.querySelector(`[data-game-arg="${index}"]`).value;
              if(value==='')return;
              let parsed=Array.isArray(schema.enum)?schema.enum[Number(value)]:schema.type==='integer'?Number(value):schema.type==='number'?Number(value):schema.type==='boolean'?value==='true':value;
              if(['object','array'].includes(schema.type)&&!Array.isArray(schema.enum)){
                try{parsed=JSON.parse(value);}catch{throw new Error(`${name} must be valid JSON.`);}
                if(schema.type==='array'?!Array.isArray(parsed):!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw new Error(`${name} must be a JSON ${schema.type}.`);
              }
              arguments_[name]=parsed;
            });
          }catch(error){output.innerHTML=`<p class="game-error" role="alert">${esc(error.message)}</p>`;return;}
          toolRunning=true;draw();selector.disabled=true;panel.querySelector('.game-tool-close').disabled=true;
          output.innerHTML='<p class="game-progress" role="status">Operation sent · waiting for the execution result…</p>';submit.disabled=true;submit.setAttribute('aria-busy','true');
          try{const result=await api('/api/games/'+encodeURIComponent(game.game_id)+'/tools/'+encodeURIComponent(capability),{method:'POST',body:{ref:tool.ref,arguments:arguments_,api_key_id:form.elements.api_key_id.value}});
            output.innerHTML=`<div class="game-tool-output" role="status"><small>Complete · ${walletMoney(result.usage?.credits_charged)} · ${esc(result.request_id||'')}</small><pre>${esc(JSON.stringify(result.result,null,2))}</pre><details class="game-operation-trace"><summary>Source evidence</summary><p>${/^https?:\/\//.test(result.result?.source_url||'')?`<a href="${esc(result.result.source_url)}" target="_blank" rel="noopener noreferrer">Open source</a>`:'Source URL unavailable for this operation.'} · ${esc(result.result?.captured_at||'')}</p></details></div>`;
          }catch(error){output.innerHTML=`<p class="game-error" role="alert">${esc(error.message)}${error.requestId?` · ${esc(error.requestId)}`:''}${error.usage?` · ${walletMoney(error.usage.credits_charged)} charged`:''}</p>`;}
          finally{toolRunning=false;draw();selector.disabled=false;panel.querySelector('.game-tool-close').disabled=false;submit.disabled=false;submit.removeAttribute('aria-busy');}
        };
      }
      selector.onchange=renderOperation;renderOperation();
    }catch(error){const box=$('#game-tool-options',panel);if(currentPanel===panelRun&&box)box.innerHTML=`<p class="game-error" role="alert">${esc(error.message)}</p>`;}
  }
  function showTool(game,capability){
    if(toolRunning)return;
    panelRun++;
    const panel=$('#game-tool-panel',detail),match=capability==='game.matches.analyze';
    const hero=capability==='mlbb.reference.hero',items=capability.endsWith('.items'),league=capability.startsWith('league.reference');
    panel.innerHTML=`<section class="game-tool-runner"><header><div><span class="overline">RUN INSIDE OPENCRAWL</span><h3>${esc((game.capabilities||[]).find(c=>c.id===capability)?.name||capability)}</h3><p>${match?'Paste your own matches, oldest first. This works for any game.':league?'Fetch the published patch reference; no extra game key required.':'Bundled historical MLBB data; dates and attribution appear with the result.'}</p></div><button type="button" class="game-tool-close" aria-label="Close tool">×</button></header>${keys.length?`<form id="game-tool-form"><label>${match?'Match results (JSON array)':hero?'Hero name or ID':items?'Item name or category':'Name, role or lane'}${match?'<textarea name="match_results" rows="7" required spellcheck="false" placeholder=\'[{&quot;win&quot;:true,&quot;hero&quot;:&quot;Fanny&quot;,&quot;kills&quot;:8,&quot;deaths&quot;:2,&quot;assists&quot;:5}]\'></textarea>':`<input name="query" maxlength="60" ${hero?'required':''} placeholder="${hero?'Lancelot':items?'Blade':league?'Ahri':'jungle'}">`}</label><label>OpenCrawl API key<select name="api_key_id">${keys.map(k=>`<option value="${esc(k.id)}">${esc(k.name)} · ${esc(k.prefix)}…</option>`).join('')}</select></label><button class="btn primary" type="submit">Run · 1 credit ${icon('arrow')}</button></form>`:`<p>Create an OpenCrawl API key to record and run this tool.</p><a data-link class="btn primary" href="/dashboard/api-keys">Create API key</a>`}<div id="game-tool-output" aria-live="polite"></div></section>`;
    panel.querySelector('.game-tool-close').onclick=()=>{panelRun++;panel.replaceChildren();};
    panel.scrollIntoView({behavior:'smooth',block:'nearest'});
    const form=$('#game-tool-form',panel);if(!form)return;
    form.onsubmit=async event=>{
      event.preventDefault();if(toolRunning)return;
      const output=$('#game-tool-output',panel),submit=form.querySelector('button[type="submit"]');
      let arguments_;
      try{arguments_=match?{matches:JSON.parse(form.elements.match_results.value)}:hero?{hero:form.elements.query.value}:{query:form.elements.query.value};}
      catch(error){output.innerHTML='<p class="game-error" role="alert">Match results must be valid JSON.</p>';return;}
      if(match&&!Array.isArray(arguments_.matches)){output.innerHTML='<p class="game-error" role="alert">Match results must be a JSON array.</p>';return;}
      toolRunning=true;draw();panel.querySelector('.game-tool-close').disabled=true;
      output.innerHTML='<p class="game-progress" role="status">Tool sent · waiting for execution result…</p>';submit.disabled=true;submit.setAttribute('aria-busy','true');
      try{
        const response=await api('/api/games/'+encodeURIComponent(game.game_id)+'/tools/'+encodeURIComponent(capability),{method:'POST',body:{api_key_id:form.elements.api_key_id.value,arguments:arguments_}});
        const data=response.result||{},provenance=data.provenance||{},rows=data.results||[];
        const summary=match?`<article><strong>${fmt(data.overall?.games)} matches · ${fmt(data.overall?.win_rate)}% wins</strong><p>Recent 10: ${fmt(data.recent_10?.win_rate)}% · KDA ${fmt(data.overall?.kda)} · ${fmt(data.current_streak?.games)} ${esc(data.current_streak?.outcome||'')} streak</p></article>`:data.hero?`<article><strong>${esc(data.hero.name)} · ${esc(data.hero.role)}</strong><p>Lanes: ${esc((data.hero.lanes||[]).join(', '))}</p><p>Synergies: ${esc((data.hero.synergies||[]).join(', '))}</p><p>Community counters: ${esc((data.hero.counters||[]).join(', '))}</p></article>`:`<p>${fmt(data.total)} matches · showing ${fmt(rows.length)}</p><div class="game-tool-rows">${rows.map(row=>`<article><strong>${esc(row.name)}</strong><span>${esc(row.role||(row.roles||[]).join(', ')||row.category||'')} ${row.cost?' · '+esc(row.cost)+' gold':''}</span></article>`).join('')}</div>`;
        output.innerHTML=`<div class="game-tool-output" role="status">${summary}<small>${match?'Calculated from your supplied games.':league?`Data Dragon version ${esc(provenance.version||'')} · <a href="${esc(provenance.source||'')}" target="_blank" rel="noopener noreferrer">Riot documentation</a>`:`Snapshot ${esc(provenance.hero_revision||'')} (heroes) / ${esc(provenance.item_revision||'')} (items) · <a href="${esc(provenance.source||'')}" target="_blank" rel="noopener noreferrer">Source and license: MIT</a>`} · ${walletMoney(response.usage?.credits_charged)} · ${esc(response.request_id||'')}</small><details><summary>Full structured result</summary><pre>${esc(JSON.stringify(data,null,2))}</pre></details></div>`;
      }catch(error){output.innerHTML=`<p class="game-error" role="alert">${esc(error.message)}${error.requestId?` · ${esc(error.requestId)}`:''}</p>`;}
      finally{toolRunning=false;draw();panel.querySelector('.game-tool-close').disabled=false;submit.disabled=false;submit.removeAttribute('aria-busy');}
    };
  }
  filter.oninput=()=>{gamePage=0;draw();};draw();if(games.length)select(games[0].game_id);
}
async function dashRepositories(){
  const keyData=await api('/api/api-keys');
  const keys=(keyData.keys||[]).filter(k=>!k.revoked_at&&(!k.expires_at||new Date(k.expires_at)>new Date()));
  if(!keys.length){
    dashboardShell('repositories',`${pageHead('REPOSITORY INTELLIGENCE','Explore public code','Discover repositories and inspect documented API surfaces.')}<section class="search-key-lock">${icon('key')}<div><h2>Create an API key first</h2><p>Repository searches are recorded as runs against your key.</p></div><a class="btn primary" data-link href="/dashboard/api-keys">Create API key</a></section>`);
    return;
  }
  dashboardShell('repositories',`${pageHead('REPOSITORY INTELLIGENCE','Explore public code','Search GitHub projects, inspect licenses and map published OpenAPI specs.')}<section class="repo-workspace"><form id="repo-form" class="repo-search"><label for="repo-query">Search topic or paste owner/repository</label><div><input id="repo-query" required maxlength="160" autocomplete="off" placeholder="MLBB data tools, replay analysis, or owner/repo"><button class="btn primary" id="repo-submit">Investigate ${icon('arrow')}</button></div><details><summary>API key</summary><select id="repo-key">${keys.map(k=>`<option value="${esc(k.id)}">${esc(k.name)} · ${esc(k.prefix)}…</option>`).join('')}</select></details></form><div class="repo-suggestions"><button data-repo-example="MLBB data tools">MLBB data tools</button><button data-repo-example="game replay analysis">Replay analysis</button><button data-repo-example="openapi game statistics">Game APIs</button></div><div id="repo-results" aria-live="polite"><p class="repo-empty">Results will show source links, license, freshness and available API specifications.</p></div></section>`);
  const field=$('#repo-query'),results=$('#repo-results'),button=$('#repo-submit');
  field.value=(new URLSearchParams(location.search).get('query')||'').slice(0,160);
  const source=name=>/^[\w.-]+\/[\w.-]+$/.test(name||'')?'https://github.com/'+name:'';
  const pushed=value=>value&&Number.isFinite(Date.parse(value))?' · Last push '+new Date(value).toLocaleDateString():'';
  let activeRun=0,requestPending=false;
  async function investigate(input,forceInspect=false){
    const value=String(input||'').trim();if(!value||requestPending)return;
    const inspect=forceInspect||/^([\w.-]+\/[\w.-]+|https:\/\/github\.com\/[\w.-]+\/[\w.-]+(?:\.git)?)$/i.test(value);
    const run=++activeRun;
    requestPending=true;button.disabled=true;button.setAttribute('aria-busy','true');
    $$('[data-repo-example]').forEach(item=>item.disabled=true);
    results.innerHTML=`<p class="repo-progress" role="status">${inspect?'Inspecting public repository files':'Searching public GitHub data'} · waiting for GitHub response…</p>`;
    try{
      const response=await api('/api/repos/'+(inspect?'inspect':'search'),{method:'POST',body:{[inspect?'repository':'query']:value,api_key_id:$('#repo-key').value}});
      if(run!==activeRun)return;
      const data=response.result||{},usage=response.usage||{};
      const metric=`${walletMoney(usage.credits_charged)} · ${fmt(usage.github_api_calls)} GitHub requests${response.request_id?' · '+esc(response.request_id):''}`;
      if(!inspect){
        const rows=data.repositories||[];
        results.innerHTML=`<header class="repo-result-head"><h2>${fmt(rows.length)} public repositories</h2><small>${esc(metric)}${data.incomplete_results?' · GitHub returned partial results':''}</small></header>${rows.length?`<div class="repo-result-list">${rows.map(row=>{const url=source(row.name);return `<article class="repo-card"><div><strong>${esc(row.name)}</strong><p>${esc(row.description||'No description provided.')}</p><small>${esc(row.language||'Language unknown')} · ${fmt(row.stars)} stars · ${esc(row.license||'License not declared')}${esc(pushed(row.updated_at))}</small></div><div class="repo-card-actions">${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">View source</a><button data-repo-inspect="${esc(row.name)}">Inspect ${icon('arrow')}</button>`:''}</div></article>`}).join('')}</div>`:'<p class="repo-empty">No public repositories found. Try a broader topic.</p>'}`;
        $$('[data-repo-inspect]',results).forEach(item=>item.onclick=()=>{if(requestPending)return;field.value=item.dataset.repoInspect;investigate(field.value,true)});
      }else{
        const url=source(data.repository),specs=data.api_specs||[],files=data.candidate_files||[];
        results.innerHTML=`<header class="repo-result-head"><div><span class="overline">PUBLIC REPOSITORY</span><h2>${esc(data.repository||value)}</h2><p>${esc(data.description||'No description provided.')}</p><small>${esc(data.language||'Language unknown')} · ${fmt(data.stars)} stars · ${esc(data.license||'License not declared')}${esc(pushed(data.pushed_at))} · ${esc(metric)}</small></div>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">View on GitHub ${icon('arrow')}</a>`:''}</header>${data.tree_truncated?'<p class="repo-note">The file tree was truncated; findings cover the inspected portion.</p>':''}<section class="repo-findings"><h3>Documented API specs</h3>${specs.length?specs.map(spec=>`<article><a href="${esc(spec.url)}" target="_blank" rel="noopener noreferrer">${esc(spec.path)}</a><small>${spec.parsed?`${fmt((spec.endpoints||[]).length)} endpoint examples · ${fmt((spec.oauth_scopes||[]).length)} OAuth scope names`:'Specification could not be parsed'}</small>${(spec.endpoints||[]).length?`<div class="repo-endpoints">${spec.endpoints.slice(0,20).map(ep=>`<code>${esc(ep.method)} ${esc(ep.path)}</code>`).join('')}</div>`:''}${(spec.oauth_scopes||[]).length?`<p>Documented scopes: ${esc(spec.oauth_scopes.join(', '))}</p>`:''}</article>`).join(''):'<p class="repo-empty">No small OpenAPI spec was found in the inspected tree.</p>'}<h3>Promising source paths</h3>${files.length?`<div class="repo-files">${files.slice(0,35).map(file=>`<a href="${esc(file.url)}" target="_blank" rel="noopener noreferrer">${esc(file.path)}</a>`).join('')}</div>`:'<p class="repo-empty">No API related paths found in the inspected tree.</p>'}</section>${url?`<button class="btn" id="repo-clone">Copy public clone command</button>`:''}`;
        const operations=specs.flatMap(spec=>(spec.operations||[]).map(operation=>({...operation,spec_url:spec.url}))).slice(0,30);
        if(operations.length){
          $('.repo-findings',results)?.insertAdjacentHTML('afterbegin',`<section class="repo-operations"><h3>Documented read operations</h3><p>GET and HEAD paths found in public API specifications. Discovery only; these are not executed from this page.</p><div>${operations.map(op=>`<article><div><strong>${esc(op.name||'Read operation')}</strong><code>${esc(op.method)} ${esc(op.path)}</code><small>${(op.inputs||[]).length?'Inputs: '+esc(op.inputs.join(', ')):'No path or query inputs documented'} · ${op.requires_auth?'Access declared':'No authentication declared'}</small></div><a href="${esc(op.spec_url||'#')}" target="_blank" rel="noopener noreferrer">Specification</a></article>`).join('')}</div></section>`);
        }
        $('#repo-clone')?.addEventListener('click',event=>copyText('git clone '+url+'.git',event.currentTarget));
      }
    }catch(error){if(run===activeRun)results.innerHTML=`<p class="repo-error" role="alert">${esc(error.message)}${error.requestId?` · ${esc(error.requestId)}`:''}</p>`;}
    finally{if(run===activeRun){requestPending=false;button.disabled=false;button.removeAttribute('aria-busy');$$('[data-repo-example]').forEach(item=>item.disabled=false);}}
  }
  $('#repo-form').onsubmit=e=>{e.preventDefault();investigate(field.value)};
  $$('[data-repo-example]').forEach(item=>item.onclick=()=>{if(requestPending)return;field.value=item.dataset.repoExample;investigate(field.value)});
}
async function dashPublicData(){
  const keyData=await api('/api/api-keys');
  const keys=(keyData.keys||[]).filter(k=>!k.revoked_at&&(!k.expires_at||new Date(k.expires_at)>new Date()));
  dashboardShell('data',`${pageHead('PUBLIC DATA','Read the source. Follow the evidence.','Search public indexes, extract a document, or follow evidence across URLs you choose.')}<section class="game-tool-runner"><form id="public-data-form" class="form-stack"><label>Operation<select name="operation"><option value="search">Search public indexes</option><option value="research">Research linked sources</option><option value="extract">Extract a document</option><option value="discover">Discover published interfaces</option></select></label><label id="public-data-urls-field">Source URLs<textarea name="urls" rows="4" maxlength="8000" spellcheck="false" placeholder="https://example.com/public-report"></textarea><small id="public-data-url-help">One URL per line, up to 10. Research stays within these origins.</small></label><div id="public-data-search-fields" class="form-stack" hidden><label>Search terms<input name="search_query" maxlength="200" placeholder="What are you looking for?"></label><label>Results per index<input name="search_limit" type="number" min="1" max="10" value="5"></label><fieldset><legend>Public indexes</legend><label class="check"><input type="checkbox" name="source" value="wikipedia" checked> Encyclopedia</label><label class="check"><input type="checkbox" name="source" value="openalex" checked> Research catalog</label><label class="check"><input type="checkbox" name="source" value="crossref" checked> Publication records</label></fieldset></div><div id="public-data-research-fields" class="form-stack"><label>Evidence to look for<input name="query" maxlength="500" placeholder="Topic, question, or terms"></label><label>Page budget<input name="max_pages" type="number" min="1" max="20" value="5" required></label></div><label>Execution key<select name="api_key_id" required>${keys.map(k=>`<option value="${esc(k.id)}">${esc(k.name||k.prefix)}</option>`).join('')}</select></label><p id="public-data-budget" role="status"></p><button type="submit" class="btn primary" ${keys.length?'':'disabled'}>Run public data tool ${icon('arrow')}</button>${keys.length?'':'<p>Create an active API key to execute. <a data-link href="/dashboard/api-keys">Open API Keys</a></p>'}</form><div id="public-data-output" class="game-tool-output" aria-live="polite"></div></section>`);
  const form=$('#public-data-form'),output=$('#public-data-output'),button=form.querySelector('button[type=submit]');
  let running=false;
  const update=()=>{
    const research=form.elements.operation.value==='research',search=form.elements.operation.value==='search';
    $('#public-data-research-fields').hidden=!research;
    $('#public-data-search-fields').hidden=!search;
    $('#public-data-urls-field').hidden=search;
    form.elements.urls.required=!search;
    form.elements.search_query.required=search;
    form.elements.search_limit.disabled=!search;
    form.elements.max_pages.disabled=!research;
    $('#public-data-url-help').textContent=research?'One URL per line, up to 10. Research follows links within these origins.':'Enter one public HTTP(S) URL.';
    const budget=search?form.querySelectorAll('[name="source"]:checked').length:research?Math.max(1,Math.min(20,Number(form.elements.max_pages.value)||5))*2:1;
    $('#public-data-budget').textContent=`Reserve up to ${walletMoney(2+budget*3)}. Final charge is metered in USD wallet balance per attempted source fetch${research?', including crawl-policy checks':''}. Unused credits are released.`;
  };
  form.elements.operation.onchange=update;form.elements.max_pages.oninput=update;form.querySelectorAll('[name="source"]').forEach(input=>input.onchange=update);update();
  form.onsubmit=async event=>{
    event.preventDefault();if(running)return;
    const operation=form.elements.operation.value,urls=form.elements.urls.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
    try{if(operation!=='search')urls.forEach(value=>{const url=new URL(value);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw new Error();});}
    catch{output.textContent='Use complete HTTP(S) URLs without embedded credentials.';return;}
    const pages=Number(form.elements.max_pages.value);
    if(operation!=='search'&&(!urls.length||(operation==='research'&&(urls.length>10||urls.length>pages))||(operation!=='research'&&urls.length!==1))){output.textContent='Use one URL for extraction or discovery. Research accepts up to 10 URLs within its page budget.';return;}
    const sources=[...form.querySelectorAll('[name="source"]:checked')].map(input=>input.value);
    if(operation==='search'&&(!sources.length||form.elements.search_query.value.trim().length<2)){output.textContent='Enter at least two search characters and select a public index.';return;}
    const args=operation==='search'?{query:form.elements.search_query.value.trim(),sources,limit:Number(form.elements.search_limit.value)}:operation==='research'?{urls,query:form.elements.query.value,max_pages:pages}:{url:urls[0]};
    running=true;busy(button,true,'Collecting public sources…');form.setAttribute('aria-busy','true');
    output.innerHTML='<p role="status">Request submitted. Waiting for source evidence; collection is bounded to 25 seconds.</p>';
    try{
      const response=await api('/api/public-data/'+operation,{method:'POST',body:{api_key_id:form.elements.api_key_id.value,arguments:args}});
      if(!output.isConnected)return;
      const result=response.result||{},items=result.results||result.evidence||(result.source_url?[result]:[]);
      output.innerHTML=`<h3>${result.partial?'Partial evidence collected':'Collection complete'}</h3><p>${walletMoney(response.usage?.credits_charged||0)} charged · <code>${esc(response.request_id)}</code></p>${items.length?'':'<p>No matching public records were returned.</p>'}${items.map(source=>`<article><h4>${esc(source.title||source.source_url)}</h4><p>${esc((source.snippets||[source.snippet||source.text||'']).join(' ').slice(0,1600))}</p><a href="${esc(source.source_url||source.url)}" target="_blank" rel="noopener noreferrer">Open source</a><small> · ${source.sources?`${source.sources.length} public ${source.sources.length===1?'index':'indexes'}`:esc(source.captured_at||'')}</small></article>`).join('')}<details class="game-operation-trace"><summary>Structured results &amp; source diagnostics</summary><pre>${esc(JSON.stringify(result,null,2))}</pre></details>`;
    }catch(error){if(output.isConnected){
      output.innerHTML=`<p>${esc(error.message)}</p>${error.requestId?`<p>Request <code>${esc(error.requestId)}</code>${error.usage?` · ${walletMoney(error.usage.credits_charged)} charged`:''}</p>`:''}${error.result?`<details><summary>Source diagnostics</summary><pre>${esc(JSON.stringify(error.result,null,2))}</pre></details>`:''}`;
    }}
    finally{running=false;busy(button,false);form.removeAttribute('aria-busy');}
  };
}


async function dashSmartScrape(){
  const keyData=await api('/api/api-keys');
  const keys=(keyData.keys||[]).filter(k=>!k.revoked_at&&(!k.expires_at||new Date(k.expires_at)>new Date()));
  if(!keys.length){
    dashboardShell('scrape',
      pageHead('SMART SCRAPE','Turn a page into usable data','OpenCrawl starts with bounded HTTP extraction when it can and escalates only when the requested result needs rendering.')+
      '<section class="search-key-lock">'+icon('key')+'<div><h2>Create an API key first</h2><p>Scrapes are metered runs and need an execution key.</p></div><a class="btn primary" data-link href="/dashboard/api-keys">Create API key</a></section>'
    );
    return;
  }
  const keyOptions=keys.map((k,i)=>'<option value="'+esc(k.id)+'" '+(i===0?'selected':'')+'>'+esc(k.name||k.prefix)+' · '+esc(k.prefix)+'…</option>').join('');
  dashboardShell('scrape',
    pageHead('SMART SCRAPE','Turn a page into usable data','Request the output you need. Auto mode uses the least expensive reliable path and only renders when required.','<a class="btn" data-link href="/dashboard/datasets">'+icon('docs')+' Datasets</a>')+
    '<section class="game-tool-runner"><form id="smart-scrape-form" class="form-stack">'+
      '<label>Public page URL<input name="url" type="url" required maxlength="2000" placeholder="https://example.com/pricing"></label>'+
      '<div class="search-advanced-grid">'+
        '<label>Execution mode<select name="mode"><option value="auto">Auto · cheapest reliable path</option><option value="http">HTTP only · never render</option><option value="rendered">Rendered · JavaScript/browser-backed</option></select></label>'+
        '<label>Execution key<select name="api_key_id" required>'+keyOptions+'</select></label>'+
        '<label>Timeout (ms)<input name="timeout_ms" type="number" min="1000" max="60000" value="30000"></label>'+
        '<label>Max response bytes<input name="max_bytes" type="number" min="32000" max="8000000" value="2000000"></label>'+
      '</div>'+
      '<fieldset><legend>Output formats</legend>'+
        '<label class="check"><input name="format" type="checkbox" value="markdown" checked> Markdown</label>'+
        '<label class="check"><input name="format" type="checkbox" value="links" checked> Links</label>'+
        '<label class="check"><input name="format" type="checkbox" value="raw_html"> Raw HTML</label>'+
        '<label class="check"><input name="format" type="checkbox" value="html"> Clean rendered HTML</label>'+
        '<label class="check"><input name="format" type="checkbox" value="screenshot"> Screenshot</label>'+
      '</fieldset>'+
      '<div class="search-advanced-checks"><label><input name="only_main_content" type="checkbox" checked> Prefer main content</label><label><input name="mobile" type="checkbox"> Render as mobile</label></div>'+
      '<div class="search-advanced-grid"><label>Wait before extraction (ms)<input name="wait_ms" type="number" min="0" max="10000" value="0"></label><label>Rendered cache age (ms)<input name="max_age_ms" type="number" min="0" max="86400000" value="0"></label></div>'+
      '<p class="search-security">'+icon('shield')+' Public targets only · private-network targets blocked · provider routing stays behind OpenCrawl</p>'+
      '<div class="execution-budget-controls"><label>Maximum spend (USD)<input name="max_spend_usd" type="number" min="0" step="0.0002" placeholder="Set after cost review"></label><p>Review creates no provider work. Confirmation rechecks price and wallet balance before execution.</p></div>'+
      '<button class="btn primary" id="smart-scrape-review" type="submit">Review scrape cost '+icon('arrow')+'</button>'+
      '<section id="smart-scrape-quote" class="card execution-cost-review" hidden aria-live="polite"></section>'+
      '<button class="btn primary" id="smart-scrape-confirm" type="button" hidden>Confirm and scrape page</button>'+
    '</form><div id="smart-scrape-output" class="game-tool-output" aria-live="polite"></div></section>'
  );

  const form=$('#smart-scrape-form'),quoteBox=$('#smart-scrape-quote'),confirmButton=$('#smart-scrape-confirm'),reviewButton=$('#smart-scrape-review'),output=$('#smart-scrape-output');
  let reviewed=null,running=false,generation=0;

  const requestBody=()=>({
    url:String(form.elements.url.value||'').trim(),
    mode:form.elements.mode.value,
    formats:[...form.querySelectorAll('[name="format"]:checked')].map(input=>input.value),
    only_main_content:Boolean(form.elements.only_main_content.checked),
    mobile:Boolean(form.elements.mobile.checked),
    timeout_ms:Number(form.elements.timeout_ms.value),
    max_bytes:Number(form.elements.max_bytes.value),
    wait_ms:Number(form.elements.wait_ms.value),
    max_age_ms:Number(form.elements.max_age_ms.value),
    api_key_id:form.elements.api_key_id.value
  });
  const invalidate=()=>{
    generation++;
    reviewed=null;
    quoteBox.hidden=true;
    confirmButton.hidden=true;
    output.innerHTML='';
  };
  form.querySelectorAll('input:not([name="max_spend_usd"]),select').forEach(node=>{
    node.addEventListener(node.type==='checkbox'||node.tagName==='SELECT'?'change':'input',invalidate);
  });

  form.onsubmit=async event=>{
    event.preventDefault();
    if(running)return;
    const body=requestBody();
    try{
      const parsed=new URL(body.url);
      if(!['http:','https:'].includes(parsed.protocol)||parsed.username||parsed.password)throw new Error();
    }catch{
      output.innerHTML='<p class="game-error" role="alert">Use a complete public HTTP(S) URL without embedded credentials.</p>';
      return;
    }
    if(!body.formats.length){
      output.innerHTML='<p class="game-error" role="alert">Select at least one output format.</p>';
      return;
    }
    const run=++generation;
    busy(reviewButton,true,'Reviewing cost…');
    try{
      const data=await api('/api/scrape/quote',{method:'POST',body});
      if(run!==generation||!form.isConnected)return;
      reviewed=data.quote||{};
      const plan=data.scrape||{};
      const scale=Number(reviewed.wallet_units_per_usd||5000);
      const maximum=Number(reviewed.maximum_charge_credits??reviewed.credits??0);
      form.elements.max_spend_usd.value=(scale>0?maximum/scale:0).toFixed(4);
      quoteBox.hidden=false;
      quoteBox.innerHTML='<header><span><span class="overline">COST REVIEW</span><h3>Maximum reservation '+esc(walletMoney(maximum,{wallet_units_per_usd:scale}))+'</h3></span><span class="badge '+(reviewed.affordable?'success':'danger')+'">'+(reviewed.affordable?'Wallet ready':'Insufficient wallet')+'</span></header>'+
        '<p>'+(plan.execution_mode==='rendered'?'This request needs the rendered path because of its output/options.':'Auto/HTTP mode can begin with the low-cost bounded HTTP extractor.')+' The final charge stays below this reservation and unused funds are released.</p>'+
        '<div class="ih-inspector-grid"><div><small>Execution plan</small><b>'+esc(plan.execution_mode||body.mode)+'</b></div><div><small>Formats</small><b>'+esc((plan.formats||body.formats).join(', '))+'</b></div><div><small>Available</small><b>'+esc(walletMoney(reviewed.available_credits||0,{wallet_units_per_usd:scale}))+'</b></div><div><small>Timeout</small><b>'+fmt(body.timeout_ms)+' ms</b></div></div>';
      confirmButton.hidden=false;
      confirmButton.disabled=!reviewed.affordable;
      confirmButton.textContent=reviewed.affordable?'Confirm and scrape page':'Add wallet balance to continue';
    }catch(error){
      reviewed=null;
      quoteBox.hidden=true;
      confirmButton.hidden=true;
      output.innerHTML='<p class="game-error" role="alert">'+esc(error.message)+'</p>';
    }finally{busy(reviewButton,false);}
  };

  confirmButton.onclick=async()=>{
    if(!reviewed||running||confirmButton.disabled)return;
    const body=requestBody(),scale=Number(reviewed.wallet_units_per_usd||5000);
    const spendUsd=Number(form.elements.max_spend_usd.value);
    if(!Number.isFinite(spendUsd)||spendUsd<0){
      output.innerHTML='<p class="game-error" role="alert">Enter a valid non-negative maximum spend.</p>';
      return;
    }
    body.max_charge_credits=Math.floor(spendUsd*scale+1e-9);
    body.quote_revision=reviewed.quote_revision;
    running=true;
    busy(confirmButton,true,'Scraping page…');
    output.innerHTML='<p role="status">Collecting the public page. The run may stay on bounded HTTP or escalate to rendered extraction according to the reviewed request.</p>';
    try{
      const response=await api('/api/scrape/run',{method:'POST',body});
      if(!output.isConnected)return;
      const result=response.result||{},summary=response.summary||{},dataset=response.dataset;
      const tabs=[];
      if(result.markdown)tabs.push(['Markdown','<pre>'+esc(result.markdown)+'</pre>']);
      if(result.text)tabs.push(['Text','<pre>'+esc(result.text)+'</pre>']);
      if(result.html)tabs.push(['HTML','<pre>'+esc(result.html)+'</pre>']);
      if(result.raw_html)tabs.push(['Raw HTML','<pre>'+esc(result.raw_html)+'</pre>']);
      if((result.links||[]).length)tabs.push(['Links','<div class="repo-files">'+result.links.slice(0,500).map(link=>'<a href="'+esc(link)+'" target="_blank" rel="noopener noreferrer">'+esc(link)+'</a>').join('')+'</div>']);
      if(result.screenshot)tabs.push(['Screenshot','<a href="'+esc(result.screenshot)+'" target="_blank" rel="noopener noreferrer">Open captured screenshot '+icon('external')+'</a>']);
      output.innerHTML='<header class="repo-result-head"><div><span class="overline">SCRAPE COMPLETE · '+esc(String(summary.execution_path||'').toUpperCase())+'</span><h2>'+esc(result.title||new URL(result.url||body.url).hostname)+'</h2><p>'+esc(result.description||result.url||body.url)+'</p><small>'+esc(walletMoney(response.usage?.credits_charged||0))+' charged · <code>'+esc(response.request_id||'')+'</code>'+(summary.status_code?' · HTTP '+esc(summary.status_code):'')+'</small></div>'+(dataset?.id?'<a data-link href="/dashboard/datasets?dataset='+encodeURIComponent(dataset.id)+'">Open saved dataset '+icon('arrow')+'</a>':'')+'</header>'+
        '<section class="stats-grid">'+
          stat('Execution path',esc(summary.execution_path||'—'),'OpenCrawl routing outcome')+
          stat('Readable bytes',fmt(summary.text_bytes||0),'Normalized text')+
          stat('Links',fmt(summary.links||0),'Discovered public URLs')+
          stat('Formats',fmt((summary.formats||[]).length),'Returned output types')+
        '</section>'+
        (tabs.length?'<div class="scrape-result-tabs">'+tabs.map(([label,body],index)=>'<details '+(index===0?'open':'')+'><summary>'+esc(label)+'</summary><div class="crawl-content">'+body+'</div></details>').join('')+'</div>':'<p class="repo-empty">The page returned no displayable content.</p>')+
        '<details class="game-operation-trace"><summary>Structured scrape result</summary><pre>'+esc(JSON.stringify(result,null,2))+'</pre></details>'+
        (response.warnings?.length?'<div class="notice warning">'+response.warnings.map(x=>esc(x.message)).join('<br>')+'</div>':'');
      bindCommon();
    }catch(error){
      const usage=error.usage?(' · '+walletMoney(error.usage.credits_charged||0)+' charged'):'';
      output.innerHTML='<p class="game-error" role="alert">'+esc(error.message)+(error.requestId?' · '+esc(error.requestId):'')+esc(usage)+'</p>';
    }finally{
      running=false;
      reviewed=null;
      quoteBox.hidden=true;
      confirmButton.hidden=true;
      busy(confirmButton,false);
    }
  };
}

async function dashSiteMap(){
  const keyData=await api('/api/api-keys');
  const keys=(keyData.keys||[]).filter(k=>!k.revoked_at&&(!k.expires_at||new Date(k.expires_at)>new Date()));
  if(!keys.length){
    dashboardShell('map',
      pageHead('SITE MAP','Map a site before crawling it','Discover and classify public URLs without fetching every page.')+
      '<section class="search-key-lock">'+icon('key')+'<div><h2>Create an API key first</h2><p>Site maps are metered runs and need an execution key.</p></div><a class="btn primary" data-link href="/dashboard/api-keys">Create API key</a></section>'
    );
    return;
  }
  const keyOptions=keys.map((k,i)=>'<option value="'+esc(k.id)+'" '+(i===0?'selected':'')+'>'+esc(k.name||k.prefix)+' · '+esc(k.prefix)+'…</option>').join('');
  dashboardShell('map',
    pageHead('SITE MAP','Map a site before crawling it','Discover URLs cheaply, classify the structure, then save the result as a dataset.','<a class="btn" data-link href="/dashboard/datasets">'+icon('docs')+' Datasets</a>')+
    '<section class="game-tool-runner"><form id="site-map-form" class="form-stack">'+
      '<label>Site root<input name="url" type="url" required maxlength="2000" placeholder="https://example.com"></label>'+
      '<label>Focus (optional)<input name="search" maxlength="160" placeholder="docs, pricing, products, careers…"></label>'+
      '<div class="search-advanced-grid"><label>Maximum URLs<input name="limit" type="number" min="1" max="1000" value="250" required></label>'+
      '<label>Sitemap behavior<select name="sitemap_mode"><option value="auto">Use sitemap when available</option><option value="only">Sitemap only</option><option value="ignore">Ignore sitemap</option></select></label>'+
      '<label>Execution key<select name="api_key_id" required>'+keyOptions+'</select></label></div>'+
      '<label class="check"><input name="include_subdomains" type="checkbox"> Include subdomains</label>'+
      '<div class="execution-budget-controls"><label>Maximum spend (USD)<input name="max_spend_usd" type="number" min="0" step="0.0002" placeholder="Set after cost review"></label><p>Review creates no provider work. Confirmation rechecks price and wallet balance before execution.</p></div>'+
      '<button class="btn primary" id="site-map-review" type="submit">Review map cost '+icon('arrow')+'</button>'+
      '<section id="site-map-quote" class="card execution-cost-review" hidden aria-live="polite"></section>'+
      '<button class="btn primary" id="site-map-confirm" type="button" hidden>Confirm and map site</button>'+
    '</form><div id="site-map-output" class="game-tool-output" aria-live="polite"></div></section>'
  );
  const form=$('#site-map-form'),quoteBox=$('#site-map-quote'),confirmButton=$('#site-map-confirm'),reviewButton=$('#site-map-review'),output=$('#site-map-output');
  let reviewed=null,running=false,generation=0;

  const requestBody=()=>({
    url:String(form.elements.url.value||'').trim(),
    search:String(form.elements.search.value||'').trim(),
    limit:Number(form.elements.limit.value),
    sitemap_mode:form.elements.sitemap_mode.value,
    include_subdomains:Boolean(form.elements.include_subdomains.checked),
    api_key_id:form.elements.api_key_id.value
  });
  const invalidate=()=>{
    generation++;
    reviewed=null;
    quoteBox.hidden=true;
    confirmButton.hidden=true;
    output.innerHTML='';
  };
  ['url','search','limit','sitemap_mode','include_subdomains','api_key_id'].forEach(name=>{
    form.elements[name].addEventListener(name==='search'||name==='url'||name==='limit'?'input':'change',invalidate);
  });

  form.onsubmit=async event=>{
    event.preventDefault();
    if(running)return;
    const body=requestBody();
    try{
      const parsed=new URL(body.url);
      if(!['http:','https:'].includes(parsed.protocol)||parsed.username||parsed.password)throw new Error();
    }catch{
      output.innerHTML='<p class="game-error" role="alert">Use a complete public HTTP(S) URL without embedded credentials.</p>';
      return;
    }
    const run=++generation;
    busy(reviewButton,true,'Reviewing cost…');
    try{
      const data=await api('/api/site-map/quote',{method:'POST',body});
      if(run!==generation||!form.isConnected)return;
      reviewed=data.quote||{};
      const scale=Number(reviewed.wallet_units_per_usd||5000);
      const maximum=Number(reviewed.maximum_charge_credits??reviewed.credits??0);
      const usd=scale>0?maximum/scale:0;
      form.elements.max_spend_usd.value=usd.toFixed(4);
      quoteBox.hidden=false;
      quoteBox.innerHTML='<header><span><span class="overline">COST REVIEW</span><h3>Maximum reservation '+esc(walletMoney(maximum,{wallet_units_per_usd:scale}))+'</h3></span><span class="badge '+(reviewed.affordable?'success':'danger')+'">'+(reviewed.affordable?'Wallet ready':'Insufficient wallet')+'</span></header>'+
        '<p>This is a ceiling, not a guaranteed charge. Unused reservation is released. Mapping returns URL structure only; it does not download every page body.</p>'+
        '<div class="ih-inspector-grid"><div><small>Available</small><b>'+esc(walletMoney(reviewed.available_credits||0,{wallet_units_per_usd:scale}))+'</b></div><div><small>URL limit</small><b>'+fmt(body.limit)+'</b></div><div><small>Sitemap</small><b>'+esc(body.sitemap_mode)+'</b></div><div><small>Subdomains</small><b>'+(body.include_subdomains?'Included':'Root host only')+'</b></div></div>';
      confirmButton.hidden=false;
      confirmButton.disabled=!reviewed.affordable;
      confirmButton.textContent=reviewed.affordable?'Confirm and map site':'Add wallet balance to continue';
    }catch(error){
      reviewed=null;
      quoteBox.hidden=true;
      confirmButton.hidden=true;
      output.innerHTML='<p class="game-error" role="alert">'+esc(error.message)+'</p>';
    }finally{busy(reviewButton,false);}
  };

  confirmButton.onclick=async()=>{
    if(!reviewed||running||confirmButton.disabled)return;
    const body=requestBody();
    const scale=Number(reviewed.wallet_units_per_usd||5000);
    const spendUsd=Number(form.elements.max_spend_usd.value);
    if(!Number.isFinite(spendUsd)||spendUsd<0){
      output.innerHTML='<p class="game-error" role="alert">Enter a valid non-negative maximum spend.</p>';
      return;
    }
    body.max_charge_credits=Math.floor(spendUsd*scale+1e-9);
    body.quote_revision=reviewed.quote_revision;
    running=true;
    busy(confirmButton,true,'Mapping site…');
    output.innerHTML='<p role="status">Mapping public URLs. OpenCrawl will use the available site-map route and keep provider details behind the capability boundary.</p>';
    try{
      const response=await api('/api/site-map/run',{method:'POST',body});
      if(!output.isConnected)return;
      const result=response.result||{},rows=result.urls||[],summary=response.summary||{},dataset=response.dataset;
      const categoryEntries=Object.entries(summary.categories||{});
      const visible=rows.slice(0,200);
      output.innerHTML='<header class="repo-result-head"><div><span class="overline">SITE MAP COMPLETE</span><h2>'+fmt(summary.returned_urls||rows.length)+' URLs mapped</h2><p>'+esc(result.root_url||body.url)+'</p><small>'+esc(walletMoney(response.usage?.credits_charged||0))+' charged · <code>'+esc(response.request_id||'')+'</code>'+(summary.truncated?' · result limit reached':'')+'</small></div>'+(dataset?.id?'<a data-link href="/dashboard/datasets?dataset='+encodeURIComponent(dataset.id)+'">Open saved dataset '+icon('arrow')+'</a>':'')+'</header>'+
        '<section class="stats-grid">'+
          stat('Returned URLs',fmt(summary.returned_urls||0),'Normalized same-site records')+
          stat('Reported URLs',fmt(summary.reported_urls||0),'Before OpenCrawl normalization')+
          stat('Max depth',fmt(summary.max_depth||0),'URL path segments')+
          stat('Categories',fmt(categoryEntries.length),'Heuristic URL classes')+
        '</section>'+
        (categoryEntries.length?'<div class="repo-suggestions">'+categoryEntries.map(([name,count])=>'<span class="badge">'+esc(name)+' · '+fmt(count)+'</span>').join('')+'</div>':'')+
        (visible.length?'<div class="repo-result-list">'+visible.map(row=>'<article class="repo-card"><div><strong>'+esc(row.title||row.path||row.url)+'</strong><p>'+esc(row.url)+'</p><small>'+esc(row.category)+' · depth '+fmt(row.depth)+(row.parent_url?' · parent '+esc(row.parent_url):'')+'</small></div><div class="repo-card-actions"><a href="'+esc(row.url)+'" target="_blank" rel="noopener noreferrer">Open URL</a></div></article>').join('')+'</div>':'<p class="repo-empty">No same-site public URLs were returned.</p>')+
        (rows.length>visible.length?'<p class="repo-note">Showing the first '+fmt(visible.length)+' URLs here. The saved dataset contains all returned rows.</p>':'')+
        '<details class="game-operation-trace"><summary>Structured map result</summary><pre>'+esc(JSON.stringify(result,null,2))+'</pre></details>'+
        (response.warnings?.length?'<div class="notice warning">'+response.warnings.map(x=>esc(x.message)).join('<br>')+'</div>':'');
      bindCommon();
    }catch(error){
      const usage=error.usage?(' · '+walletMoney(error.usage.credits_charged||0)+' charged'):'';
      output.innerHTML='<p class="game-error" role="alert">'+esc(error.message)+(error.requestId?' · '+esc(error.requestId):'')+esc(usage)+'</p>';
    }finally{
      running=false;
      reviewed=null;
      quoteBox.hidden=true;
      confirmButton.hidden=true;
      busy(confirmButton,false);
    }
  };
}


async function dashCapabilities(){
  const [catalog,keyData,dashboard]=await Promise.all([
    api('/api/capabilities?pack=web&limit=100'),
    api('/api/api-keys'),
    api('/api/dashboard')
  ]);
  const capabilities=catalog.capabilities||[];
  const keys=(keyData.keys||[]).filter(function(k){return !k.revoked_at&&(!k.expires_at||new Date(k.expires_at)>new Date());});
  const account=dashboard.account||{};
  const available=Number(account.monthly_credits||0)+Number(account.purchased_credits||0)-Number(account.reserved_credits||0);
  if(!keys.length){
    dashboardShell('capabilities',
      pageHeadline('WEB CAPABILITIES','Run registered web tools','Use the same semantic capabilities exposed to agents, with real wallet accounting and saved outputs.')+
      '<section class="search-key-lock">'+icon('key')+'<div><small>API KEY REQUIRED</small><h2>Create an API key first.</h2><p>Workbench runs are metered and attributed to an owned execution key.</p></div><a class="btn primary" data-link href="/dashboard/api-keys">Create API key</a></section>'
    );
    return;
  }
  if(!capabilities.length){
    dashboardShell('capabilities',
      pageHeadline('WEB CAPABILITIES','Run registered web tools','Only real registered capabilities appear here.')+
      '<div class="smart-empty">'+icon('activity')+'<span><b>No web capabilities are registered.</b><p>The workbench will not invent placeholder tools.</p></span></div>'
    );
    return;
  }

  const capabilityOptions=capabilities.map(function(cap){
    return '<option value="'+esc(cap.id)+'">'+esc(cap.name)+' · '+esc(cap.id)+'</option>';
  }).join('');
  const keyOptions=keys.map(function(k,i){
    return '<option value="'+esc(k.id)+'" '+(i===0?'selected':'')+'>'+esc(k.name)+' · '+esc(k.prefix)+'…</option>';
  }).join('');

  dashboardShell('capabilities',
    pageHeadline('WEB CAPABILITIES','Capability workbench','Run OpenCrawl semantic capabilities directly. Provider routing stays behind the product boundary; cost, output and failures stay visible.','<a class="btn" data-link href="/dashboard/datasets">'+icon('docs')+' Datasets</a>')+
    '<section class="cap-workbench">'+
      '<aside class="cap-workbench-picker">'+
        '<label>Capability<select id="cap-id">'+capabilityOptions+'</select></label>'+
        '<div id="cap-summary" class="cap-summary" aria-live="polite"></div>'+
        '<details><summary>Execution identity</summary><label>API key<select id="cap-key">'+keyOptions+'</select></label><p>'+icon('shield')+' Scoped key · server-held provider credentials</p></details>'+
        '<a data-link href="/docs/tool-mesh">How semantic routing works →</a>'+
      '</aside>'+
      '<section class="cap-workbench-main">'+
        '<form id="cap-form" class="form-stack">'+
          '<div id="cap-fields" class="cap-fields" aria-live="polite"></div>'+
          '<details class="cap-raw"><summary>Raw JSON arguments</summary>'+
            '<label class="check"><input id="cap-use-raw" type="checkbox"> Use raw JSON instead of generated fields</label>'+
            '<textarea id="cap-raw-json" rows="9" spellcheck="false">{}</textarea>'+
          '</details>'+
          '<div class="execution-budget-controls"><label>Maximum spend (USD)<input id="cap-spend-limit" type="number" min="0" step="0.0002" placeholder="Use reviewed maximum"></label><p>Review first. The server rechecks the quote and wallet before execution.</p></div>'+
          '<p class="search-security">'+icon('shield')+' Read-only workbench · <span id="cap-wallet">'+esc(walletMoney(available))+'</span> wallet available</p>'+
          '<button class="btn primary" id="cap-review" type="submit">Review cost '+icon('arrow')+'</button>'+
          '<section id="cap-cost-review" class="card execution-cost-review" hidden aria-live="polite"></section>'+
        '</form>'+
        '<section id="cap-output" class="cap-output" hidden aria-live="polite"></section>'+
      '</section>'+
    '</section>'
  );
  bindCommon();

  const selector=$('#cap-id'),form=$('#cap-form'),fields=$('#cap-fields'),summary=$('#cap-summary');
  const rawToggle=$('#cap-use-raw'),raw=$('#cap-raw-json'),cost=$('#cap-cost-review'),output=$('#cap-output');
  const spend=$('#cap-spend-limit'),review=$('#cap-review');
  let spec=null,reviewed=null,quoteGeneration=0,running=false;

  function invalidate(){
    quoteGeneration++;reviewed=null;cost.hidden=true;
    const old=$('#cap-confirm');if(old)old.remove();
  }

  function renderFields(schema){
    const properties=(schema&&schema.properties)||{};
    const required=new Set((schema&&schema.required)||[]);
    const entries=Object.entries(properties);
    if(!entries.length){
      fields.innerHTML='<div class="notice">This capability has no generated fields. Use Raw JSON arguments.</div>';
      rawToggle.checked=true;
      raw.closest('details').open=true;
      return;
    }
    fields.innerHTML=entries.map(function(entry,index){
      const name=entry[0],field=entry[1]||{},req=required.has(name);
      const label=esc(name)+(req?' *':'');
      const desc=field.description?'<small>'+esc(field.description)+'</small>':'';
      const attr=' data-cap-field="'+esc(name)+'" data-cap-index="'+index+'" '+(req?'required':'');
      let control='';
      if(Array.isArray(field.enum)){
        control='<select'+attr+'><option value="">Choose a value</option>'+field.enum.map(function(value,i){return '<option value="'+i+'">'+esc(String(value))+'</option>';}).join('')+'</select>';
      }else if(field.type==='boolean'){
        control='<select'+attr+'><option value="">Choose</option><option value="true">True</option><option value="false">False</option></select>';
      }else if(field.type==='object'||field.type==='array'){
        control='<textarea'+attr+' rows="5" spellcheck="false" placeholder="'+(field.type==='array'?'[]':'{}')+'"></textarea>';
      }else{
        const numeric=field.type==='integer'||field.type==='number';
        const urlish=field.format==='uri'||/url$/i.test(name);
        control='<input'+attr+' type="'+(numeric?'number':urlish?'url':'text')+'" '+(numeric?'step="'+(field.type==='integer'?'1':'any')+'" ':'')+(field.minimum!=null?'min="'+esc(String(field.minimum))+'" ':'')+(field.maximum!=null?'max="'+esc(String(field.maximum))+'" ':'')+'>';
      }
      return '<label class="cap-field"><span>'+label+'</span>'+control+desc+'</label>';
    }).join('');
  }

  function collectArguments(){
    if(rawToggle.checked){
      let parsed;
      try{parsed=JSON.parse(raw.value||'{}');}catch{throw new Error('Raw arguments must be valid JSON.');}
      if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw new Error('Raw arguments must be a JSON object.');
      return parsed;
    }
    const schema=(spec&&spec.capability&&spec.capability.input_schema)||{};
    const properties=schema.properties||{};
    const args={};
    fields.querySelectorAll('[data-cap-field]').forEach(function(control){
      const name=control.dataset.capField,field=properties[name]||{},value=control.value;
      if(value==='')return;
      let parsed=value;
      if(Array.isArray(field.enum))parsed=field.enum[Number(value)];
      else if(field.type==='integer')parsed=Number.parseInt(value,10);
      else if(field.type==='number')parsed=Number(value);
      else if(field.type==='boolean')parsed=value==='true';
      else if(field.type==='object'||field.type==='array'){
        try{parsed=JSON.parse(value);}catch{throw new Error(name+' must be valid JSON.');}
        if(field.type==='array'&&!Array.isArray(parsed))throw new Error(name+' must be a JSON array.');
        if(field.type==='object'&&(!parsed||Array.isArray(parsed)||typeof parsed!=='object'))throw new Error(name+' must be a JSON object.');
      }
      args[name]=parsed;
    });
    return args;
  }

  async function loadCapability(){
    invalidate();output.hidden=true;review.disabled=true;
    summary.innerHTML='<p>Loading registered schema and availability…</p>';
    fields.innerHTML='<p>Inspecting capability…</p>';
    try{
      const data=await api('/api/capabilities/'+encodeURIComponent(selector.value));
      spec=data;
      const cap=data.capability||{},availability=data.availability||{};
      summary.innerHTML='<span class="overline">'+esc(cap.id||'CAPABILITY')+'</span><h2>'+esc(cap.name||cap.id||'Capability')+'</h2><p>'+esc(cap.description||'')+'</p>'+
        '<div class="cap-tags">'+(cap.tags||[]).slice(0,8).map(function(tag){return '<span>'+esc(tag)+'</span>';}).join('')+'</div>'+
        (availability.interactive_ready?'<p class="cap-ready">'+icon('check')+' Interactive execution ready · '+esc(String(availability.available_routes||0))+' route(s)</p>':'<div class="notice warning"><b>Not runnable here yet.</b><p>'+esc(availability.reason||'No synchronous route is available.')+'</p></div>');
      renderFields(cap.input_schema||{});
      raw.value='{}';
      review.disabled=!availability.interactive_ready;
      review.textContent=availability.interactive_ready?'Review cost':'Unavailable in interactive workbench';
    }catch(error){
      spec=null;summary.innerHTML='<div class="notice danger">'+esc(error.message)+'</div>';
      fields.innerHTML='';review.disabled=true;
    }
  }

  selector.addEventListener('change',loadCapability);
  form.addEventListener('input',function(e){if(e.target!==rawToggle)invalidate();});
  form.addEventListener('change',invalidate);
  rawToggle.addEventListener('change',function(){
    fields.hidden=rawToggle.checked;
    raw.disabled=!rawToggle.checked;
    invalidate();
  });
  raw.disabled=true;

  form.addEventListener('submit',async function(e){
    e.preventDefault();
    if(running||!spec||!spec.availability.interactive_ready)return;
    let args;
    try{args=collectArguments();}catch(error){toast(error.message,'error');return;}
    const key=$('#cap-key').value;
    const fingerprint=JSON.stringify({id:selector.value,key:key,args:args,limit:spend.value});
    if(!reviewed||reviewed.fingerprint!==fingerprint||!e.submitter||e.submitter.id!=='cap-confirm'){
      const generation=quoteGeneration;
      review.disabled=true;cost.hidden=false;cost.textContent='Checking current price…';
      try{
        const data=await api('/api/capabilities/'+encodeURIComponent(selector.value)+'/quote',{method:'POST',body:{api_key_id:key,arguments:args}});
        if(generation!==quoteGeneration||!form.isConnected)return;
        const q=data.quote||{},scale=Number(q.wallet_units_per_usd);
        if(!Number.isSafeInteger(q.credits)||q.credits<0||typeof q.quote_revision!=='string'||q.quote_revision.length!==64||!Number.isFinite(scale)||scale<=0)
          throw new Error('The server did not return a valid execution quote.');
        let cap=q.credits;
        if(spend.value!==''){
          const converted=Number(spend.value)*scale;
          if(!Number.isFinite(converted)||converted<0||Math.abs(converted-Math.round(converted))>0.000001||converted>1000000000)
            throw new Error('Choose a spending limit in whole wallet units.');
          cap=Math.round(converted);
        }
        const affordable=q.affordable===true,within=q.credits<=cap;
        cost.innerHTML='<h3>Review this capability run</h3><p><b>'+esc(walletMoney(q.credits,q))+' maximum reservation</b></p><p>'+esc(walletMoney(q.available_credits,q))+' available · '+esc(walletMoney(cap,q))+' spending limit</p>'+
          '<p>The reservation is the ceiling. Final measured work may charge less; unused funds are released.</p>'+
          (!within?'<p role="alert">This execution exceeds your spending limit.</p>':'')+
          (!affordable?'<p role="alert">Your wallet cannot cover this reservation.</p><a class="btn" data-link href="/dashboard/wallet">Open wallet</a>':'');
        bindCommon();
        if(affordable&&within){
          reviewed={fingerprint:fingerprint,quote:q,cap:cap,args:args,key:key};
          cost.insertAdjacentHTML('beforeend','<button class="btn primary" id="cap-confirm" type="submit">Confirm & run</button>');
        }
      }catch(error){reviewed=null;cost.innerHTML='<p role="alert">'+esc(error.message)+'</p>';}
      finally{review.disabled=false;}
      return;
    }

    running=true;review.disabled=true;
    const confirmed=reviewed;reviewed=null;cost.hidden=true;
    output.hidden=false;output.innerHTML='<div class="ih-execution-progress" role="status"><div class="ih-execution-head"><span class="ih-execution-symbol">⚙️</span><div><b>Executing capability</b><p>'+esc(selector.value)+'</p></div></div><ol class="ih-execution-stages"><li class="done">Quote confirmed</li><li class="done">Wallet reservation requested</li><li class="current">Routing read-only capability</li><li>Saving bounded output</li><li>Complete</li></ol></div>';
    try{
      const data=await api('/api/capabilities/'+encodeURIComponent(selector.value)+'/run',{method:'POST',body:{
        api_key_id:confirmed.key,
        arguments:confirmed.args,
        max_charge_credits:confirmed.cap,
        quote_revision:confirmed.quote.quote_revision
      }});
      const result=data.result||{},attempts=result.route_attempts||[];
      output.innerHTML='<div class="cap-result-head"><div><span class="overline">COMPLETE</span><h2>'+esc((spec.capability||{}).name||selector.value)+'</h2><p>'+esc(walletMoney((data.usage||{}).credits_charged||0))+' charged · <code>'+esc(data.request_id||'')+'</code></p></div><button class="btn" id="cap-rerun">Run again</button></div>'+
        (data.dataset&&data.dataset.id?'<a class="btn primary" data-link href="/dashboard/datasets?dataset='+encodeURIComponent(data.dataset.id)+'">Open saved dataset</a>':'')+
        ((data.warnings||[]).map(function(w){return '<div class="notice warning">'+esc(w.message||'Output was not saved.')+'</div>';}).join(''))+
        '<details open><summary>Result</summary><pre>'+esc(JSON.stringify(result.data,null,2))+'</pre></details>'+
        '<details><summary>Execution trace</summary><p>'+attempts.length+' route attempt(s) · '+esc(String(result.duration_ms||0))+' ms</p><pre>'+esc(JSON.stringify(attempts,null,2))+'</pre></details>';
      bindCommon();
      $('#cap-rerun')?.addEventListener('click',function(){output.hidden=true;form.scrollIntoView({behavior:'smooth',block:'start'});});
      api('/api/dashboard').then(function(d){
        const a=d.account||{},balance=Number(a.monthly_credits||0)+Number(a.purchased_credits||0)-Number(a.reserved_credits||0);
        const node=$('#cap-wallet');if(node)node.textContent=walletMoney(balance);
      }).catch(function(){});
    }catch(error){
      output.innerHTML='<div class="search-error" role="alert">'+icon('shield')+'<div><h3>Capability did not complete</h3><p>'+esc(error.message)+'</p>'+(error.requestId?'<p>Request <code>'+esc(error.requestId)+'</code></p>':'')+(error.usage?'<p>'+esc(walletMoney(error.usage.credits_charged||0))+' charged for measured work.</p>':'')+'<button class="btn small" id="cap-retry">Review again</button></div></div>';
      $('#cap-retry')?.addEventListener('click',function(){output.hidden=true;form.requestSubmit(review);});
    }finally{
      running=false;review.disabled=false;invalidate();
    }
  });

  await loadCapability();
}

async function dashStructuredExtract(){
  const [keyData,recentData]=await Promise.all([
    api('/api/api-keys'),
    api('/api/extract/runs?limit=12&offset=0')
  ]);
  const keys=(keyData.keys||[]).filter(k=>!k.revoked_at&&(!k.expires_at||new Date(k.expires_at)>new Date()));
  if(!keys.length){
    dashboardShell('extract',
      pageHead('STRUCTURED EXTRACT','Turn public pages into validated JSON','Give OpenCrawl public URLs, extraction instructions and an optional JSON Schema. The owned run continues even if you leave the page.')+
      '<section class="search-key-lock">'+icon('key')+'<div><h2>Create an API key first</h2><p>Extraction is metered background work and needs an owned execution key.</p></div><a class="btn primary" data-link href="/dashboard/api-keys">Create API key</a></section>'
    );
    return;
  }

  const keyOptions=keys.map((k,i)=>'<option value="'+esc(k.id)+'" '+(i===0?'selected':'')+'>'+esc(k.name||k.prefix)+' · '+esc(k.prefix)+'…</option>').join('');
  const recent=recentData.runs||[];

  const runCard=run=>{
    const status=String(run.status||'unknown');
    const tone=status==='completed'?'success':status==='failed'||status==='cancelled'?'danger':'';
    const result=run.result||{};
    return '<article class="repo-card" data-extract-run="'+esc(run.id)+'"><div><span class="badge '+tone+'">'+esc(status)+'</span><strong>'+esc(run.capability||'Structured extraction')+'</strong><p><code>'+esc(run.id||'')+'</code></p><small>'+fmt(run.input?.source_count||0)+' source(s) · '+esc(when(run.updated_at))+(run.credits_charged!=null?' · '+esc(walletMoney(run.credits_charged))+' charged':'')+'</small></div><div class="repo-card-actions">'+(run.dataset_id?'<a data-link href="/dashboard/datasets?dataset='+encodeURIComponent(run.dataset_id)+'">Open dataset</a>':'<button class="btn small" type="button" data-open-extract="'+esc(run.id)+'">Inspect</button>')+'</div></article>';
  };

  dashboardShell('extract',
    pageHead('STRUCTURED EXTRACT','Turn public pages into validated JSON','Use one to twenty public URLs, describe the fields you need, and optionally provide JSON Schema. OpenCrawl owns the durable run, billing and saved output.','<a class="btn" data-link href="/docs/structured-extract">'+icon('docs')+' Guide</a>')+
    '<section class="game-tool-runner"><form id="extract-form" class="form-stack">'+
      '<label>Public source URLs <small>One per line · 1–20</small><textarea name="urls" rows="5" maxlength="82000" required placeholder="https://example.com/pricing\nhttps://example.com/features"></textarea></label>'+
      '<label>What should OpenCrawl extract?<textarea name="prompt" rows="4" maxlength="4000" required placeholder="Extract plan name, monthly price, currency and included features. Do not invent missing fields."></textarea></label>'+
      '<div class="search-advanced-grid">'+
        '<label>Effort<select name="effort"><option value="low">Low · small focused extraction</option><option value="medium" selected>Medium · balanced</option><option value="high">High · deeper research</option></select></label>'+
        '<label>Execution key<select name="api_key_id" required>'+keyOptions+'</select></label>'+
      '</div>'+
      '<details class="game-operation-trace"><summary>Optional JSON Schema</summary><p>Use Schema when you need predictable downstream fields. Missing source values remain missing; OpenCrawl validates the returned structure instead of fabricating them.</p><textarea name="schema" rows="10" maxlength="32768" spellcheck="false" placeholder=\'{"type":"object","required":["plans"],"properties":{"plans":{"type":"array","items":{"type":"object","properties":{"name":{"type":"string"},"price":{"type":"number"}}}}}}\'></textarea></details>'+
      '<div class="execution-budget-controls"><label>Maximum spend (USD)<input name="max_spend_usd" type="number" min="0" step="0.0002" placeholder="Set after cost review"></label><p>Review creates no provider work. Confirmation reserves the ceiling; unused funds are released.</p></div>'+
      '<p class="search-security">'+icon('shield')+' Public targets only · private networks blocked · zero-data-retention requested upstream · provider job identity stays private</p>'+
      '<button class="btn primary" id="extract-review" type="submit">Review extraction cost '+icon('arrow')+'</button>'+
      '<section id="extract-quote" class="card execution-cost-review" hidden aria-live="polite"></section>'+
      '<button class="btn primary" id="extract-confirm" type="button" hidden>Confirm and start extraction</button>'+
    '</form><div id="extract-output" class="game-tool-output" aria-live="polite"></div></section>'+
    '<section class="repo-workspace"><header class="repo-result-head"><div><span class="overline">RECENT EXTRACT RUNS</span><h2>Owned background work</h2><p>Reopen a run after leaving this page. Completed output lives in Datasets.</p></div></header><div id="extract-recent">'+(recent.length?'<div class="repo-result-list">'+recent.map(runCard).join('')+'</div>':'<p class="repo-empty">No structured extraction runs yet.</p>')+'</div></section>'
  );

  const form=$('#extract-form'),reviewButton=$('#extract-review'),confirmButton=$('#extract-confirm'),quoteBox=$('#extract-quote'),output=$('#extract-output');
  let reviewed=null,running=false,generation=0;

  const bodyFromForm=()=>{
    const urls=String(form.elements.urls.value||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean);
    let schema=null;
    const rawSchema=String(form.elements.schema.value||'').trim();
    if(rawSchema){
      try{schema=JSON.parse(rawSchema);}catch{throw new Error('JSON Schema must be valid JSON.');}
      if(!schema||Array.isArray(schema)||typeof schema!=='object')throw new Error('JSON Schema must be a JSON object.');
    }
    return {
      urls,
      prompt:String(form.elements.prompt.value||'').trim(),
      effort:form.elements.effort.value,
      api_key_id:form.elements.api_key_id.value,
      ...(schema?{schema}:{}),
    };
  };

  const invalidate=()=>{
    generation++;
    reviewed=null;
    quoteBox.hidden=true;
    confirmButton.hidden=true;
  };
  form.querySelectorAll('textarea,input:not([name="max_spend_usd"]),select').forEach(node=>{
    node.addEventListener(node.tagName==='SELECT'?'change':'input',invalidate);
  });

  const showRun=run=>{
    const result=run.result||{},stateName=String(run.status||'unknown');
    const active=['queued','running','waiting'].includes(stateName);
    output.innerHTML='<header class="repo-result-head"><div><span class="overline">EXTRACT RUN · '+esc(stateName.toUpperCase())+'</span><h2>'+fmt(run.input?.source_count||0)+' public source(s)</h2><p><code>'+esc(run.id||'')+'</code></p><small>'+esc(walletMoney(run.credits_reserved||0))+' reserved'+(run.credits_charged!=null?' · '+esc(walletMoney(run.credits_charged||0))+' charged':'')+'</small></div>'+(run.dataset_id?'<a class="btn primary" data-link href="/dashboard/datasets?dataset='+encodeURIComponent(run.dataset_id)+'">Open saved dataset '+icon('arrow')+'</a>':'')+'</header>'+
      '<section class="stats-grid">'+
        stat('State',esc(stateName),active?'Background execution is durable':'Terminal run state')+
        stat('Records',fmt(result.record_count||0),'Saved structured rows')+
        stat('Schema',result.schema_valid==null?'Not supplied':result.schema_valid?'Valid':'Mismatch','OpenCrawl validation')+
        stat('Attempts',fmt(run.attempts||0),'Owned worker leases')+
      '</section>'+
      (result.schema_errors?.length?'<div class="notice warning"><b>Schema mismatches</b><br>'+result.schema_errors.slice(0,20).map(esc).join('<br>')+'</div>':'')+
      (stateName==='waiting'?'<p class="repo-note">The upstream extraction is running. You can leave this page; OpenCrawl will keep the run and settle it when the protected worker observes a terminal result.</p>':'')+
      (stateName==='queued'?'<button class="btn danger small" id="cancel-extract-run" type="button">Cancel queued run</button>':'')+
      (stateName==='failed'?'<div class="notice danger">Extraction failed with <code>'+esc(run.error_code||'unknown_error')+'</code>. Usage reflects only the measured work OpenCrawl settled.</div>':'')+
      (stateName==='cancelled'?'<div class="notice">This extraction was cancelled before upstream work began.</div>':'');
    bindCommon();
    $('#cancel-extract-run')?.addEventListener('click',async()=>{
      try{
        const data=await api('/api/extract/runs/'+encodeURIComponent(run.id)+'/cancel',{method:'POST',body:{}});
        showRun(data.run);
      }catch(error){toast(error.message,'error');}
    });
  };

  const pollRun=async runId=>{
    clearTimeout(state.extractRunTimer);
    if(!location.pathname.endsWith('/extract'))return;
    try{
      const data=await api('/api/extract/runs/'+encodeURIComponent(runId));
      const run=data.run||{};
      showRun(run);
      if(['queued','running','waiting'].includes(String(run.status||''))){
        state.extractRunTimer=setTimeout(()=>pollRun(runId),15000);
      }
    }catch(error){
      output.innerHTML='<p class="game-error" role="alert">'+esc(error.message)+'</p>';
    }
  };

  $$('[data-open-extract]').forEach(button=>button.addEventListener('click',()=>pollRun(button.dataset.openExtract)));

  form.onsubmit=async event=>{
    event.preventDefault();
    if(running)return;
    let body;
    try{body=bodyFromForm();}catch(error){output.innerHTML='<p class="game-error" role="alert">'+esc(error.message)+'</p>';return;}
    if(body.urls.length<1||body.urls.length>20){
      output.innerHTML='<p class="game-error" role="alert">Enter between 1 and 20 public URLs, one per line.</p>';return;
    }
    if(body.prompt.length<3){
      output.innerHTML='<p class="game-error" role="alert">Describe what you want extracted.</p>';return;
    }
    const run=++generation;
    busy(reviewButton,true,'Reviewing cost…');
    try{
      const data=await api('/api/extract/quote',{method:'POST',body});
      if(run!==generation||!form.isConnected)return;
      reviewed=data.quote||{};
      const meta=data.extract||{},scale=Number(reviewed.wallet_units_per_usd||5000);
      const maximum=Number(reviewed.maximum_charge_credits??reviewed.credits??0);
      form.elements.max_spend_usd.value=(scale>0?maximum/scale:0).toFixed(4);
      quoteBox.hidden=false;
      quoteBox.innerHTML='<header><span><span class="overline">COST REVIEW</span><h3>Maximum reservation '+esc(walletMoney(maximum,{wallet_units_per_usd:scale}))+'</h3></span><span class="badge '+(reviewed.affordable?'success':'danger')+'">'+(reviewed.affordable?'Wallet ready':'Insufficient wallet')+'</span></header>'+
        '<p>This background extraction may finish after you leave the page. The accepted reservation is the ceiling; final measured work can settle lower.</p>'+
        '<div class="ih-inspector-grid"><div><small>Sources</small><b>'+fmt(meta.source_count||body.urls.length)+'</b></div><div><small>Effort</small><b>'+esc(meta.effort||body.effort)+'</b></div><div><small>Schema</small><b>'+(meta.schema_provided?'Provided':'None')+'</b></div><div><small>Available</small><b>'+esc(walletMoney(reviewed.available_credits||0,{wallet_units_per_usd:scale}))+'</b></div></div>';
      confirmButton.hidden=false;
      confirmButton.disabled=!reviewed.affordable;
      confirmButton.textContent=reviewed.affordable?'Confirm and start extraction':'Add wallet balance to continue';
    }catch(error){
      reviewed=null;quoteBox.hidden=true;confirmButton.hidden=true;
      output.innerHTML='<p class="game-error" role="alert">'+esc(error.message)+'</p>';
    }finally{busy(reviewButton,false);}
  };

  confirmButton.onclick=async()=>{
    if(!reviewed||running||confirmButton.disabled)return;
    let body;
    try{body=bodyFromForm();}catch(error){toast(error.message,'error');return;}
    const scale=Number(reviewed.wallet_units_per_usd||5000),spendUsd=Number(form.elements.max_spend_usd.value);
    if(!Number.isFinite(spendUsd)||spendUsd<0){
      output.innerHTML='<p class="game-error" role="alert">Enter a valid non-negative maximum spend.</p>';return;
    }
    body.max_charge_credits=Math.floor(spendUsd*scale+1e-9);
    body.quote_revision=reviewed.quote_revision;
    const key='extract:'+((globalThis.crypto&&typeof crypto.randomUUID==='function')?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));
    running=true;busy(confirmButton,true,'Starting extraction…');
    output.innerHTML='<p role="status">Creating an owned extraction run and launching bounded upstream work…</p>';
    try{
      const data=await api('/api/extract/runs',{method:'POST',body,headers:{'Idempotency-Key':key}});
      const run=data.run||{};
      showRun(run);
      if(['queued','running','waiting'].includes(String(run.status||''))){
        state.extractRunTimer=setTimeout(()=>pollRun(run.id),5000);
      }
    }catch(error){
      output.innerHTML='<p class="game-error" role="alert">'+esc(error.message)+(error.requestId?' · '+esc(error.requestId):'')+'</p>';
    }finally{
      running=false;reviewed=null;quoteBox.hidden=true;confirmButton.hidden=true;busy(confirmButton,false);
    }
  };
}

async function renderDashboard(){if(!await ensureMe())return;const slug=location.pathname.split('/')[2]||'overview';const routes={overview:dashOverview,playground:dashPlayground,capabilities:dashCapabilities,scrape:dashSmartScrape,map:dashSiteMap,extract:dashStructuredExtract,datasets:dashDatasets,'crawl-runs':dashCrawlRuns,runs:dashRuns,spending:dashSpending,games:dashGames,repositories:dashRepositories,data:dashPublicData,usage:dashUsage,'api-keys':dashKeys,monitors:dashMonitors,integrations:dashIntegrations,connections:dashIntegrations,mcp:dashIntegrations,wallet:dashWallet,rewards:dashRewards,billing:dashBilling,settings:dashSettings};return (routes[slug]||dashOverview)();}
async function renderRoute(){clearTransientUi();window.scrollTo(0,0);const p=location.pathname;try{if(p==='/'||p==='/pricing'||p==='/status'||p.startsWith('/docs')||p.startsWith('/legal')||LEGAL_ALIASES[p])await hydrateOptionalSession();if(p.startsWith('/dashboard'))return await renderDashboard();if(p==='/verify-email')return await renderVerify();if(p==='/login')return renderAuth('login');if(p==='/signup')return renderAuth('signup');if(p==='/forgot-password')return renderRecovery();if(p==='/reset-password')return renderRecovery(true);if(p.startsWith('/legal')||LEGAL_ALIASES[p])return renderLegal();if(p.startsWith('/docs'))return renderDocs();if(p==='/pricing')return await renderPricing();if(p==='/status')return await renderStatus();return await renderHome();}catch(error){console.error(error);if(error.status===401)return go('/login',true);app.innerHTML=`<main class="fatal"><div>${brand()}<span class="eyebrow">REQUEST FAILED</span><h1>The control plane did not answer cleanly.</h1><p>${esc(error.message)}</p><button class="btn primary" onclick="location.reload()">Try again</button></div></main>`;}}
document.addEventListener('click',e=>{
  if(e.defaultPrevented)return;
  const a=e.target.closest('[data-link]');
  if(!a||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
  e.preventDefault();
  e.stopPropagation();
  const href=a.getAttribute('href');
  if(href)go(href);
});
window.addEventListener('popstate',()=>{state.activePlayground?.abort();if(!location.pathname.startsWith('/dashboard'))clearInterval(state.gatewayTimer);clearTransientUi();renderRoute();});
window.addEventListener('pageshow',clearTransientUi);


// Shared by the product and telemetry renderers in this canonical runtime.
const statusDot = (tone = 'ok') => `<i class="ih-status-dot ${tone}"></i>`;
const runStatus = status => ['ok','accepted'].includes(String(status||'').toLowerCase()) ? 'ok' : 'warn';
const runLabel = e => {
  const ref=String(e?.capability||e?.tool_ref||'').trim();
  const named={'repo:search':'Repository search','repo:inspect':'Repository inspection',
    'mesh_execute':'Tool execution','mesh_capability_execute':'Capability execution',
    'game.matches.analyze':'Match analysis','playground:search':'Web search',
    'playground:research':'Deep research','playground:crawl':'Web crawl'};
  if(!ref)return 'Internet operation';
  if(named[ref])return named[ref];
  if(/^gamepublic:\d+\/(news|activity|achievements)$/.test(ref))
    return 'Game '+ref.split('/').at(-1).replace(/^./,letter=>letter.toUpperCase());
  if(!/[.:_-]/.test(ref))return ref;
  return ref.replace(/^.*?:/,'').replace(/[._-]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase())
    .replace(/\bMlbb\b/g,'MLBB').replace(/\bMcp\b/g,'MCP').replace(/\bApi\b/g,'API');
};
const runWorkflow = e => {
  const ref=String(e?.capability||e?.tool_ref||'').toLowerCase();
  if(/^(repo:|githubpublic:)/.test(ref))return 'Repository intelligence';
  if(/^(gamepublic:|gamecore:|mlbb[.:]|valorant[.:]|league[.:]|dota2[.:]|minecraft[.:]|genshin[.:]|hsr[.:]|zzz[.:]|roblox[.:]|osu[.:]|brawlstars[.:]|clashofclans[.:]|clashroyale[.:]|tft[.:]|steam[.:]|riot[.:]|game[.:])/.test(ref))return 'Game intelligence';
  if(/browser|sandbox/.test(ref))return 'Browser & compute';
  if(/monitor/.test(ref))return 'Monitoring';
  if(/^web\.|search|scrape|crawl|fetch|research|map|nativeweb|publicdata|firecrawl/.test(ref))return 'Web intelligence';
  return 'Tool execution';
};

function openRunInspector(event) {
  const wrap = modal(`<div class="ih-run-modal">
    <div class="modal-head"><span><span class="overline">RUN INSPECTOR</span><h2>${esc(runLabel(event))}</h2></span><button data-close aria-label="Close">×</button></div>
    <div class="ih-inspector-status"><span>${statusDot(runStatus(event.status))}<b>${esc(event.status||'unknown')}</b></span><code>${esc(event.request_id||'No request id')}</code></div>
    <div class="ih-inspector-grid">
      <div><small>Workflow</small><b>${esc(runWorkflow(event))}</b></div>
      <div><small>Spend</small><b>${walletMoney(event.credits_charged||0)}</b></div>
      <div><small>Latency</small><b>${event.latency_ms==null?'—':`${fmt(event.latency_ms)} ms`}</b></div>
      <div><small>Created</small><b>${esc(when(event.created_at))}</b></div>
    </div>
    <div class="ih-inspector-section"><span>REQUEST REFERENCE</span><div class="ih-code-line"><code>${esc(event.request_id||'—')}</code><button class="btn small" data-copy="${esc(event.request_id||'')}">${icon('copy')} Copy ID</button></div></div>
    <div class="ih-inspector-note"><b>Recorded execution</b><p>This request ID connects the operation, status, latency and credit charge in your usage ledger.</p></div>
  </div>`, true);
  bindCommon();
  return wrap;
}


